  "agility": {label:"Agilität",gender:"die",plural:"Agilitäten", ex5:[{t:1,s:"Agilität zahlt sich aus."},{t:2,s:"Ihre Agilität ist erstaunlich."},{t:3,s:"Wir trainieren unsere Agilität regelmäßig."},{t:4,s:"Agilität ist in diesem Beruf sehr wichtig."},{t:5,s:"Der Hund bewies große Agilität beim Hindernislauf."}]},
  "aging": {label:"Altern",gender:"das",plural:"—", ex5:[{t:1,s:"Der Körper ist am Altern."},{t:2,s:"Der Wein ist am Reifen."},{t:3,s:"Wir untersuchen den Prozess des Alterns."},{t:4,s:"Das Altern ist ein natürlicher Vorgang."},{t:5,s:"Sie beschäftigt sich mit dem Altern der Bevölkerung."}]},
  "agitate": {label:"aufwühlen",gender:"",plural:"—", ex5:[{t:1,s:"Rühren Sie die Lösung nicht zu schnell auf."},{t:2,s:"Der laute Lärm begann das Baby aufzuwühlen."},{t:3,s:"Die Demonstranten versammelten sich, um für bessere Arbeitsbedingungen zu agitieren."},{t:4,s:"Lass dich nicht so leicht aufwühlen."},{t:5,s:"Diese Nachricht hat ihn sehr aufgewühlt."}]},
  "agitated": {label:"aufgeregt",gender:"",plural:"—", ex5:[{t:1,s:"Er wurde zunehmend aufgeregt."},{t:2,s:"Die Menge ist sehr aufgeregt."},{t:3,s:"Die Nachricht hat sie aufgeregt."},{t:4,s:"Er wirkte sehr aufgeregt."},{t:5,s:"Nach dem Streit war sie völlig aufgeregt."}]},
  "agitating": {label:"agitierend",gender:"",plural:"—", ex5:[{t:1,s:"Er war dabei, für bessere Arbeitsbedingungen zu agitieren."},{t:2,s:"Der laute Lärm war für die Tiere im Zoo sehr aufwühlend."},{t:3,s:"Sie ist dabei, für eine Änderung der Schulpolitik zu agitieren."},{t:4,s:"Er ist ständig am Agitieren gegen das neue Gesetz."},{t:5,s:"Die Gruppe ist aktiv beim Agitieren für ihre Ziele."}]},
