  "agora": {label:"Agora",gender:"die",plural:"Agoren", ex5:[{t:1,s:"Die Agora war das Herz des antiken griechischen Stadtlebens."},{t:2,s:"Die Bürger versammelten sich auf der Agora, um Politik zu diskutieren."},{t:3,s:"Archäologen fanden die Ruinen einer großen Agora im Stadtzentrum."},{t:4,s:"Die Agora diente als Marktplatz und Treffpunkt."},{t:5,s:"Wir besuchten die historische Agora in Athen."}]},
  "agra": {label:"Agra",gender:"das",plural:"—", ex5:[{t:1,s:"Wir haben das Taj Mahal in Agra besucht."},{t:2,s:"Agra ist eine der beliebtesten Touristenstädte in Indien."},{t:3,s:"Es war sehr heiß, als wir nach Agra reisten."},{t:4,s:"Agra liegt im Bundesstaat Uttar Pradesh."},{t:5,s:"Viele Menschen reisen wegen des Taj Mahal nach Agra."}]},
  "agrarian": {label:"landwirtschaftlich",gender:"",plural:"—", ex5:[{t:1,s:"Das Land hat eine landwirtschaftliche Wirtschaft, die auf dem Reisanbau basiert."},{t:2,s:"Sie führen auf dem Land einen landwirtschaftlichen Lebensstil."},{t:3,s:"Eine landwirtschaftliche Reform war notwendig, um das Leben der Bauern zu verbessern."},{t:4,s:"Die landwirtschaftliche Produktion ist in diesem Jahr gestiegen."},{t:5,s:"Er interessiert sich für landwirtschaftliche Methoden."}]},
