  "agricultural": {label:"landwirtschaftlich",gender:"",plural:"—", ex5:[{t:1,s:"Die landwirtschaftliche Produktion ist gewachsen."},{t:2,s:"Das Land ist landwirtschaftlich genutzt."},{t:3,s:"Wir unterstützen die landwirtschaftliche Reform."},{t:4,s:"Es gibt viele landwirtschaftliche Betriebe in dieser Region."},{t:5,s:"Die landwirtschaftliche Fläche wurde erweitert."}]},
  "agriculture": {label:"Landwirtschaft",gender:"die",plural:"Landwirtschaften", ex5:[{t:1,s:"Die Landwirtschaft ist die Grundlage unserer Ernährung."},{t:2,s:"Er arbeitet in der modernen Landwirtschaft."},{t:3,s:"Die Landwirtschaft spielt eine wichtige Rolle für das Land."},{t:4,s:"Wir studieren die verschiedenen Methoden der Landwirtschaft."},{t:5,s:"Die Landwirtschaft erfordert viel harte Arbeit."}]},
