  "antidote": {label:"Gegengift",gender:"das",plural:"Gegengifte", ex5:[{t:1,s:"Das Gegengift hat ihm das Leben gerettet."},{t:2,s:"Leider ist das passende Gegengift sehr selten."},{t:3,s:"Wir haben das Gegengift rechtzeitig gefunden."},{t:4,s:"Gibt es für diese Substanz ein wirksames Gegengift?"},{t:5,s:"Das Labor produziert gerade ein neues Gegengift."}]},
  "antifreeze": {label:"Frostschutzmittel",gender:"das",plural:"Frostschutzmittel", ex5:[{t:1,s:"Vergiss nicht, vor dem Winter Frostschutzmittel in dein Auto zu füllen."},{t:2,s:"Der Mechaniker prüfte den Stand des Frostschutzmittels im Motor."},{t:3,s:"Das Frostschutzmittel verhindert, dass die Flüssigkeit im Kühler gefriert."},{t:4,s:"Ohne Frostschutzmittel kann der Motor bei Kälte Schaden nehmen."},{t:5,s:"Ich habe im Baumarkt neues Frostschutzmittel gekauft."}]},
