  "aortic": {label:"aortisch",gender:"",plural:"—", ex5:[{t:1,s:"Der Chirurg untersuchte die aortische Klappe sorgfältig."},{t:2,s:"Ein aortisches Aneurysma erfordert sofortige medizinische Hilfe."},{t:3,s:"Das Blut fließt durch den aortischen Bogen."},{t:4,s:"Sie leidet unter einem aortischen Klappenfehler."},{t:5,s:"Die aortische Wand muss stabil bleiben."}]},
  "apace": {label:"schnell",gender:"",plural:"—", ex5:[{t:1,s:"Die Arbeit ging am Vormittag schnell voran."},{t:2,s:"Die Reformen wurden unter dem neuen Leiter schnell umgesetzt."},{t:3,s:"Die Stadt wuchs in jenen Jahren sehr schnell."},{t:4,s:"Die Entwicklung schreitet schnell voran."},{t:5,s:"Wir müssen schnell handeln."}]},
  "apache": {label:"Apache",gender:"der",plural:"Apachen", ex5:[{t:1,s:"Das Volk der Apache hat eine reiche Kulturgeschichte."},{t:2,s:"Wir haben heute in der Schule viel über die Apache gelernt."},{t:3,s:"Das Museum zeigt eine Ausstellung über die Traditionen der Apache."},{t:4,s:"Die Geschichte der Apache ist sehr faszinierend."},{t:5,s:"Er interessiert sich für die Kultur der Apache."}]},
  "apart": {label:"auseinander",gender:"",plural:"—", ex5:[{t:1,s:"Sie haben sich mit der Zeit auseinander gelebt."},{t:2,s:"Das Spielzeug ist ganz einfach auseinander gefallen."},{t:3,s:"Wir haben das Gerät vorsichtig auseinander genommen."},{t:4,s:"Die beiden Häuser stehen ein Stück auseinander."},{t:5,s:"Man muss die Teile auseinander halten."}]},
