  "authored": {label:"verfasst",gender:"",plural:"—", ex5:[{t:1,s:"Sie hat viele Bücher verfasst."},{t:2,s:"Der Bericht wurde von einem Experten verfasst."},{t:3,s:"Sie haben gemeinsam eine wissenschaftliche Studie verfasst."},{t:4,s:"Der Brief, den ich verfasst habe, wurde abgeschickt."},{t:5,s:"Das Lehrbuch wurde von einem erfahrenen Team verfasst."}]},
  "authoring": {label:"das Verfassen",gender:"das",plural:"—", ex5:[{t:1,s:"Sie ist gerade mit dem Verfassen eines neuen Geschichtsbuchs beschäftigt."},{t:2,s:"Er ist sehr mit dem Verfassen seines ersten Romans beschäftigt."},{t:3,s:"Das Verfassen eines Lehrbuchs erfordert viel Recherche."},{t:4,s:"Beim Verfassen des Berichts achtete er auf jedes Detail."},{t:5,s:"Das Verfassen von Texten fällt ihr sehr leicht."}]},
