  "authorize": {label:"autorisieren",gender:"",plural:"—", ex5:[{t:1,s:"Die Manager autorisieren den Vorgang."},{t:2,s:"Die Zahlung wird gerade autorisiert."},{t:3,s:"Wir autorisieren den Zugriff auf das System."},{t:4,s:"Der Chef muss das Projekt autorisieren."},{t:5,s:"Können Sie diese Ausgabe autorisieren?"}]},
