  "axis": {label:"Achse",gender:"die",plural:"Achsen", ex5:[{t:1,s:"Die Achse neigt sich."},{t:2,s:"Die Achse ist vertikal."},{t:3,s:"Wir haben die Achse beschriftet."},{t:4,s:"Die Achse dreht sich sehr schnell."},{t:5,s:"Er hat die Achse des Rades repariert."}]},
  "axle": {label:"Achse",gender:"die",plural:"Achsen", ex5:[{t:1,s:"Die Achse hat sich gedreht."},{t:2,s:"Die Achse ist verbogen."},{t:3,s:"Wir haben die Achse geschmiert."},{t:4,s:"Die Achse des Wagens ist defekt."},{t:5,s:"Er prüfte die Achse auf Risse."}]},
  "axles": {label:"Achse",gender:"die",plural:"Achsen", ex5:[{t:1,s:"Der Mechaniker prüfte die Achsen des Lastwagens."},{t:2,s:"Beschädigte Achsen machen das Auto fahruntüchtig."},{t:3,s:"Die Räder sind fest mit den Achsen verbunden."},{t:4,s:"Die Achse des Wagens muss regelmäßig gewartet werden."},{t:5,s:"Durch den Unfall wurde die Achse verbogen."}]},
