  "aya": {label:"Aya",gender:"die",plural:"—", ex5:[{t:1,s:"Aya ist eine sehr nette Schülerin in meiner Klasse."},{t:2,s:"Ich habe Aya gestern Nachmittag in der Bibliothek getroffen."},{t:3,s:"Aya möchte in der Zukunft Ärztin werden."},{t:4,s:"Aya lernt immer sehr fleißig."},{t:5,s:"Nach der Schule bin ich mit Aya nach Hause gegangen."}]},
  "ayatollah": {label:"Ajatollah",gender:"der",plural:"Ajatollahs", ex5:[{t:1,s:"Der Ajatollah hielt eine Rede vor dem Volk."},{t:2,s:"Er ist ein hoch angesehener Ajatollah in seiner Gemeinde."},{t:3,s:"Der Ajatollah gab heute eine formelle Erklärung ab."},{t:4,s:"Viele Menschen folgen den Lehren des Ajatollahs."},{t:5,s:"Der Titel Ajatollah ist ein Zeichen großer religiöser Gelehrsamkeit."}]},
  "aye": {label:"Ja",gender:"das",plural:"—", ex5:[{t:1,s:"Das Komitee stimmte mit Ja für den neuen Plan."},{t:2,s:"Ich hörte ein lautes Ja aus dem hinteren Teil des Raumes."},{t:3,s:"Alle Mitglieder riefen Ja als Zeichen der Zustimmung."},{t:4,s:"Er gab ein klares Ja zu dem Vorschlag."},{t:5,s:"Ein Ja ist bei dieser Abstimmung erforderlich."}]},
  "ayurveda": {label:"Ayurveda",gender:"das",plural:"—", ex5:[{t:1,s:"Ayurveda konzentriert sich auf das Gleichgewicht von Geist, Körper und Seele."},{t:2,s:"Sie hat während ihrer Indienreise Ayurveda studiert."},{t:3,s:"Viele Menschen nutzen Ayurveda für natürliche Heilmethoden."},{t:4,s:"Ayurveda ist eine traditionelle indische Heilkunst."},{t:5,s:"Ich interessiere mich für die Philosophie des Ayurveda."}]},
