  "blackwood": {label:"Blackwood",gender:"",plural:"—", ex5:[{t:1,s:"Die Familie Blackwood wohnt in einem großen Haus."},{t:2,s:"Ich habe am Wochenende das Anwesen von Blackwood besucht."},{t:3,s:"Herr Blackwood ist ein sehr erfolgreicher Geschäftsmann."},{t:4,s:"Blackwood hat ein neues Unternehmen gegründet."},{t:5,s:"Wir sind bei Blackwood eingeladen."}]},
  "bladder": {label:"Blase",gender:"die",plural:"Blasen", ex5:[{t:1,s:"Der Arzt hat seine Blase untersucht."},{t:2,s:"Zu viel Wasser belastet die Blase."},{t:3,s:"Vor dem Flug muss ich meine Blase entleeren."},{t:4,s:"Er hat eine Entzündung der Blase."},{t:5,s:"Eine gesunde Blase ist wichtig für den Körper."}]},
  "blade": {label:"Klinge",gender:"die",plural:"Klingen", ex5:[{t:1,s:"Die Klinge des Messers ist sehr scharf."},{t:2,s:"Er schärfte die Klinge vor dem Gebrauch."},{t:3,s:"Das Licht reflektierte auf der Klinge."},{t:4,s:"Vorsicht, fass die Klinge nicht an!"},{t:5,s:"Er hat die alte Klinge ausgetauscht."}]},
  "bladed": {label:"klingenbesetzt",gender:"",plural:"—", ex5:[{t:1,s:"Ein klingenbesetztes Werkzeug wurde im Garten gefunden."},{t:2,s:"Er benutzte ein klingenbesetztes Gerät, um das Seil zu schneiden."},{t:3,s:"Diese klingenbesetzte Maschine hilft beim Rasenmähen."},{t:4,s:"Vorsicht beim Umgang mit klingenbesetzten Gegenständen."},{t:5,s:"Das Museum zeigt alte klingenbesetzte Waffen."}]},
  "blades": {label:"Klingen",gender:"die",plural:"—", ex5:[{t:1,s:"Die Klingen des Messers sind sehr scharf."},{t:2,s:"Er schärfte die Klingen vor dem Schneiden des Grases."},{t:3,s:"Die Klingen des Rasenmähers müssen ersetzt werden."},{t:4,s:"Vorsicht, diese Klingen sind extrem scharf."},{t:5,s:"Die Klingen dieses Mixers sind aus Edelstahl."}]},
