  "blossoms": {label:"Blüten",gender:"die",plural:"Blüten", ex5:[{t:1,s:"Die Blüten der Kirschbäume sind im Frühling wunderschön."},{t:2,s:"Der Apfelbaum trägt jedes Jahr im Mai viele Blüten."},{t:3,s:"Sie schmückte das Zimmer mit frischen Blüten."},{t:4,s:"Die Blüten fallen langsam auf den Boden."},{t:5,s:"Überall im Garten sieht man bunte Blüten."}]},
  "blot": {label:"Fleck",gender:"der",plural:"Flecken", ex5:[{t:1,s:"Ein dunkler Fleck ist auf meinem sauberen Heft."},{t:2,s:"Sie versuchte, den Fleck auf ihrem weißen Hemd zu entfernen."},{t:3,s:"Benutze ein Tuch, um den Fleck aufzusaugen."},{t:4,s:"Da ist ein kleiner Fleck auf der Tischdecke."},{t:5,s:"Ich muss diesen Fleck sofort reinigen."}]},
  "blotting": {label:"Aufsaugen",gender:"das",plural:"—", ex5:[{t:1,s:"Das Aufsaugen der Tinte erfordert ein spezielles Papier."},{t:2,s:"Sie war mit dem Aufsaugen der verschütteten Flüssigkeit beschäftigt."},{t:3,s:"Das Aufsaugen der Farbe hilft bei der Gestaltung."},{t:4,s:"Beim Aufsaugen von Öl muss man vorsichtig sein."},{t:5,s:"Durch das Aufsaugen wird das Papier wieder trocken."}]},
  "blouse": {label:"Bluse",gender:"die",plural:"Blusen", ex5:[{t:1,s:"Die Bluse hängt am Kleiderbügel."},{t:2,s:"Diese Bluse ist aus Seide."},{t:3,s:"Wir haben die Bluse sorgfältig gebügelt."},{t:4,s:"Sie trägt heute eine schöne Bluse."},{t:5,s:"Ich habe mir eine neue Bluse gekauft."}]},
  "blouses": {label:"Blusen",gender:"die",plural:"Blusen", ex5:[{t:1,s:"Sie hat drei neue Blusen für die Arbeit gekauft."},{t:2,s:"Das Geschäft bietet eine große Auswahl an Blusen."},{t:3,s:"Sie hat ihre Blusen vor dem wichtigen Meeting gebügelt."},{t:4,s:"Im Schrank hängen viele verschiedene Blusen."},{t:5,s:"Diese Blusen sind sehr pflegeleicht."}]},
  "blow": {label:"blasen",gender:"",plural:"—", ex5:[{t:1,s:"Der Wind bläst heute sehr stark."},{t:2,s:"Er bläst kräftig in das Horn."},{t:3,s:"Wir blasen die Kerzen auf der Torte aus."},{t:4,s:"Der Sturm bläst die Blätter von den Bäumen."},{t:5,s:"Sie bläst Seifenblasen im Garten."}]},
