  "bolsters": {label:"stärkt",gender:"",plural:"—", ex5:[{t:1,s:"Diese neuen Beweise stärkt seine Behauptung, unschuldig zu sein."},{t:2,s:"Eine positive Einstellung stärkt die Chancen auf Erfolg."},{t:3,s:"Das Unternehmen stärkt sein Team durch regelmäßige Schulungen."},{t:4,s:"Die Unterstützung der Familie stärkt ihn in schwierigen Zeiten."},{t:5,s:"Regelmäßige Bewegung stärkt den Körper."}]},
  "bolt": {label:"Schraube",gender:"die",plural:"Schrauben", ex5:[{t:1,s:"Die Schraube hatte sich gelockert."},{t:2,s:"Die Schraube sitzt sehr fest."},{t:3,s:"Wir haben die Schraube mit einem Werkzeug festgezogen."},{t:4,s:"Diese Schraube passt nicht in das Loch."},{t:5,s:"Ich muss noch eine Schraube an dem Stuhl festdrehen."}]},
  "bolted": {label:"verriegelt",gender:"",plural:"—", ex5:[{t:1,s:"Er hat die Tür schnell verriegelt, als er das Geräusch hörte."},{t:2,s:"Das Pferd rannte erschrocken über das Feld."},{t:3,s:"Sie hat ihr Frühstück verschlungen, bevor sie zur Arbeit eilte."},{t:4,s:"Er hat das Fenster fest verriegelt."},{t:5,s:"Die Tür war sicher verriegelt, als wir gingen."}]},
  "bolting": {label:"verriegelnd",gender:"",plural:"—", ex5:[{t:1,s:"Der Arbeiter ist gerade dabei, den Metallrahmen am Boden zu verschrauben."},{t:2,s:"Er ist damit beschäftigt, die Tür zu verriegeln, um alle zu schützen."},{t:3,s:"Das Pferd galoppierte verängstigt aus dem Stall."},{t:4,s:"Sie ist gerade beim Verschrauben der neuen Regale."},{t:5,s:"Das verriegelnd wirkende Schloss hält die Tür fest."}]},
  "bolts": {label:"Schraube",gender:"die",plural:"Schrauben", ex5:[{t:1,s:"Er zog die lockeren Schrauben am Fahrrad fest."},{t:2,s:"Die Maschine wird durch viele Schrauben zusammengehalten."},{t:3,s:"Sie kaufte im Baumarkt ein paar zusätzliche Schrauben."},{t:4,s:"Die Schraube ist fest in der Wand verankert."},{t:5,s:"Ohne die richtige Schraube hält das Regal nicht."}]},
