  "bracket": {label:"Halterung",gender:"die",plural:"Halterungen", ex5:[{t:1,s:"Die Halterung hält das Regal fest."},{t:2,s:"Die Halterung besteht aus Metall."},{t:3,s:"Wir haben die Halterung an der Wand montiert."},{t:4,s:"Ohne die richtige Halterung hält das Gerät nicht."},{t:5,s:"Ich habe eine neue Halterung für den Monitor gekauft."}]},
  "brackets": {label:"Klammern",gender:"die",plural:"Klammern", ex5:[{t:1,s:"Bitte setzen Sie die zusätzlichen Informationen in Klammern."},{t:2,s:"Der Lehrer benutzte eckige Klammern, um den Satz zu verdeutlichen."},{t:3,s:"Vergiss nicht, die Quellenangabe in Klammern zu setzen."},{t:4,s:"In diesem Text werden viele Klammern verwendet."},{t:5,s:"Setzen Sie den Begriff in Klammern, falls er unklar ist."}]},
  "brackish": {label:"brackig",gender:"",plural:"—", ex5:[{t:1,s:"Das Brunnenwasser wurde brackig und war nicht mehr trinkbar."},{t:2,s:"Brackwasser ist eine Mischung aus Salz- und Süßwasser."},{t:3,s:"Das Marschland enthielt flache, brackige Tümpel."},{t:4,s:"In brackigen Gewässern leben spezielle Fischarten."},{t:5,s:"Der Geschmack des Wassers war leicht brackig."}]},
  "brad": {label:"Brad",gender:"",plural:"—", ex5:[{t:1,s:"Brad kommt heute Abend zum Essen vorbei."},{t:2,s:"Ich habe mir dieses Buch von Brad ausgeliehen."},{t:3,s:"Brad arbeitet bei einer großen Firma in der Stadt."},{t:4,s:"Ich treffe mich später mit Brad im Park."},{t:5,s:"Brad ist ein guter Freund von mir."}]},
