  "cabling": {label:"Verkabelung",gender:"die",plural:"—", ex5:[{t:1,s:"Die Arbeiter sind mit der Verkabelung des neuen Bürogebäudes beschäftigt."},{t:2,s:"Eine ordnungsgemäße Verkabelung ist für ein schnelles Netzwerk unerlässlich."},{t:3,s:"Er spezialisiert sich auf die Verkabelung großer Schiffe."},{t:4,s:"Die Verkabelung des neuen Hauses wurde einem Fachmann überlassen."},{t:5,s:"Die Verkabelung für dieses Projekt ist komplex."}]},
  "cabo": {label:"Cabo",gender:"",plural:"—", ex5:[{t:1,s:"Wir planen eine Sommerreise nach Cabo."},{t:2,s:"Das Wetter in Cabo ist um diese Jahreszeit perfekt."},{t:3,s:"Warst du schon einmal im Urlaub in Cabo?"},{t:4,s:"Cabo ist ein beliebtes Reiseziel für Touristen."},{t:5,s:"Ich würde gerne einmal die Strände von Cabo besuchen."}]},
