  "cabrera": {label:"Cabrera",gender:"",plural:"—", ex5:[{t:1,s:"Herr Cabrera hilft uns bei dem Wissenschaftsprojekt."},{t:2,s:"Ich sah Frau Cabrera gestern in der Bibliothek."},{t:3,s:"Cabrera ist in einigen Ländern ein sehr häufiger Familienname."},{t:4,s:"Die Familie Cabrera wohnt in der Nähe."},{t:5,s:"Kennen Sie Herrn Cabrera persönlich?"}]},
  "cabs": {label:"Taxis",gender:"",plural:"—", ex5:[{t:1,s:"Vor dem Hotel warten viele Taxis."},{t:2,s:"Wir nehmen oft Taxis, wenn wir in Eile sind."},{t:3,s:"Die Straße was voll von gelben Taxis."},{t:4,s:"Taxis sind in dieser Stadt recht teuer."},{t:5,s:"Er rief zwei Taxis für die Gäste."}]},
  "cacao": {label:"Kakao",gender:"der",plural:"Kakaos", ex5:[{t:1,s:"Diese Schokolade hat einen hohen Anteil an Kakao."},{t:2,s:"Kakao wird in tropischen Regionen angebaut."},{t:3,s:"Wir haben eine Plantage für Kakao besucht."},{t:4,s:"Heiße Milch mit Kakao schmeckt im Winter herrlich."},{t:5,s:"Die Bohnen von Kakao werden getrocknet."}]},
  "cache": {label:"Cache",gender:"der",plural:"Caches", ex5:[{t:1,s:"Der Browser hat den Cache automatisch geleert."},{t:2,s:"Ein Cache hilft dabei, Webseiten schneller zu laden."},{t:3,s:"Die Daten wurden im Cache des Computers gespeichert."},{t:4,s:"Er löschte den Cache, um Speicherplatz freizugeben."},{t:5,s:"Ein versteckter Cache mit Münzen wurde im Wald gefunden."}]},
  "cached": {label:"gecacht",gender:"",plural:"—", ex5:[{t:1,s:"Die Bilder sind im Browser gecacht."},{t:2,s:"Warum sind diese Dateien nicht gecacht?"},{t:3,s:"Die Webseite hat die Daten lokal gecacht."},{t:4,s:"Er hat die Dokumente auf dem Server gecacht."},{t:5,s:"Die Grafik wird automatisch gecacht."}]},
  "caches": {label:"Caches",gender:"",plural:"—", ex5:[{t:1,s:"Eichhörnchen verstecken Futter in verschiedenen Caches."},{t:2,s:"Moderne Browser nutzen Caches für schnelleres Laden."},{t:3,s:"Die Caches des Systems müssen geleert werden."},{t:4,s:"Er fand geheime Caches mit alten Münzen."},{t:5,s:"Diese Caches speichern temporäre Dateien."}]},
  "caching": {label:"Caching",gender:"das",plural:"—", ex5:[{t:1,s:"Caching hilft dabei, die Ladezeit zu verkürzen."},{t:2,s:"Das automatische Caching spart viel Datenvolumen."},{t:3,s:"Ein fehlerhaftes Caching kann veraltete Inhalte anzeigen."},{t:4,s:"Caching ist eine wichtige Technik in der Informatik."},{t:5,s:"Das Caching von Bildern reduziert die Serverlast."}]},
  "cackling": {label:"kichern",gender:"",plural:"—", ex5:[{t:1,s:"Die Kinder kicherten über den lustigen Clown."},{t:2,s:"Ich konnte hören, wie sie im Nebenzimmer kicherten."},{t:3,s:"Die Hexe in der Geschichte kichert boshaft beim Kochen."},{t:4,s:"Sie kicherten leise über einen internen Witz."},{t:5,s:"Hör auf zu kichern, wir müssen ernst bleiben."}]},
