  "chandeliers": {label:"Kronleuchter",gender:"der",plural:"Kronleuchter", ex5:[{t:1,s:"Der Ballsaal wurde von funkelnden Kronleuchtern erhellt."},{t:2,s:"Neue Kronleuchter wurden im Theaterfoyer installiert."},{t:3,s:"Das Reinigen dieser großen Kronleuchter ist eine schwere Arbeit."},{t:4,s:"Die Kronleuchter hängen in der ganzen Galerie."},{t:5,s:"Diese Kronleuchter sind ein echter Blickfang."}]},
  "chandigarh": {label:"Chandigarh",gender:"",plural:"—", ex5:[{t:1,s:"Chandigarh ist eine geplante Stadt in Indien."},{t:2,s:"Mein Onkel wohnt jetzt in Chandigarh."},{t:3,s:"Wir haben die schönen Gärten in Chandigarh besucht."},{t:4,s:"Chandigarh ist bekannt für seine Architektur."},{t:5,s:"Die Reise nach Chandigarh war sehr interessant."}]},
