  "clare": {label:"Clare",gender:"",plural:"—", ex5:[{t:1,s:"Clare plant nächstes Jahr im Ausland zu studieren."},{t:2,s:"Ich habe Clare gestern im Café getroffen."},{t:3,s:"Clare hat eine wunderschöne Singstimme."},{t:4,s:"Clare arbeitet hart an ihrem Projekt."},{t:5,s:"Ich habe Clare lange nicht mehr gesehen."}]},
  "clarence": {label:"Clarence",gender:"",plural:"—", ex5:[{t:1,s:"Clarence ist ein sehr freundlicher Nachbar."},{t:2,s:"Hast du mit Clarence über das Projekt gesprochen?"},{t:3,s:"Clarence arbeitet in der Bibliothek in der Stadtmitte."},{t:4,s:"Clarence ist immer sehr hilfsbereit."},{t:5,s:"Ich besuche Clarence am Wochenende."}]},
  "clarendon": {label:"Clarendon",gender:"die",plural:"—", ex5:[{t:1,s:"Die Überschrift wurde in der Schriftart Clarendon gedruckt."},{t:2,s:"Clarendon ist eine klassische Serifenschrift."},{t:3,s:"Man verwendet Clarendon oft für auffällige Texte."},{t:4,s:"Ich habe ein altes Gebäude in Clarendon gesehen."},{t:5,s:"Die Clarendon sieht sehr elegant aus."}]},
  "claret": {label:"Claret",gender:"der",plural:"—", ex5:[{t:1,s:"Er genoss ein Glas Claret zum Abendessen."},{t:2,s:"Der Kellner empfahl einen guten Claret aus Bordeaux."},{t:3,s:"Das Tischtuch hatte einen Fleck von rotem Claret."},{t:4,s:"Ein Glas Claret passt gut zu diesem Fleischgericht."},{t:5,s:"Er schenkte sich etwas Claret ein."}]},
  "clarification": {label:"Klärung",gender:"die",plural:"Klärungen", ex5:[{t:1,s:"Ich brauche eine Klärung zu dieser Regel."},{t:2,s:"Sie bat um eine Klärung bezüglich der Zeit."},{t:3,s:"Der Lehrer sorgte für eine Klärung des Themas."},{t:4,s:"Die Klärung der Situation dauert an."},{t:5,s:"Wir benötigen eine schnelle Klärung dieser Frage."}]},
