  "climates": {label:"Klima",gender:"das",plural:"Klimate", ex5:[{t:1,s:"Verschiedene Regionen haben sehr unterschiedliche Klimate."},{t:2,s:"Manche Pflanzen überleben nicht in kalten Klimaten."},{t:3,s:"Der Klimawandel verändert das Klima auf der ganzen Welt."},{t:4,s:"Wir genießen das milde Klima am Mittelmeer."},{t:5,s:"Das Klima beeinflusst unseren Lebensstil."}]},
  "climatic": {label:"klimatisch",gender:"",plural:"—", ex5:[{t:1,s:"Die Region erlebt in letzter Zeit große klimatische Veränderungen."},{t:2,s:"Klimatische Bedingungen beeinflussen das Wachstum dieser Pflanzen."},{t:3,s:"Wissenschaftler untersuchen die klimatischen Daten des letzten Jahrhunderts."},{t:4,s:"Es gibt viele klimatische Unterschiede in diesem Land."},{t:5,s:"Die klimatische Lage ist für den Anbau ideal."}]},
  "climatologist": {label:"Klimatologe",gender:"der",plural:"Klimatologen", ex5:[{t:1,s:"Der Klimatologe warnte, dass die Temperaturen weltweit schnell steigen."},{t:2,s:"Viele Klimatologen analysieren die Auswirkungen der schmelzenden Gletscher."},{t:3,s:"Ein leitender Klimatologe präsentierte dem Ausschuss neue Daten."},{t:4,s:"Der Klimatologe forscht an der Universität."},{t:5,s:"Jeder Klimatologe ist besorgt über die aktuelle Entwicklung."}]},
  "climax": {label:"Höhepunkt",gender:"der",plural:"Höhepunkte", ex5:[{t:1,s:"Der Höhepunkt des Abends kam sehr spät."},{t:2,s:"Dieser Moment ist der absolute Höhepunkt der Reise."},{t:3,s:"Wir haben den Höhepunkt der Veranstaltung erreicht."},{t:4,s:"Der Film steuert auf seinen Höhepunkt zu."},{t:5,s:"Das Konzert hatte viele musikalische Höhepunkte."}]},
  "climb": {label:"klettern",gender:"",plural:"—", ex5:[{t:1,s:"Wir klettern gerne auf die Berge."},{t:2,s:"Die Kinder klettern auf den Baum im Garten."},{t:3,s:"Man muss vorsichtig sein, wenn man klettern geht."},{t:4,s:"Die Preise klettern weiter in die Höhe."},{t:5,s:"Klettern ist ein tolles Training für den ganzen Körper."}]},
  "climbed": {label:"geklettert",gender:"",plural:"—", ex5:[{t:1,s:"Die Katze ist schnell auf den hohen Baum geklettert."},{t:2,s:"Wir sind auf den Berg geklettert, um den Sonnenaufgang zu sehen."},{t:3,s:"Er ist auf das Dach geklettert, um das Leck zu reparieren."},{t:4,s:"Sie ist geschickt die Felswand hochgeklettert."},{t:5,s:"Wir sind gestern zusammen in der Halle geklettert."}]},
  "climber": {label:"Kletterer",gender:"der",plural:"Kletterer", ex5:[{t:1,s:"Der Kletterer machte eine kurze Pause."},{t:2,s:"Dieser Kletterer ist sehr fit und erfahren."},{t:3,s:"Wir haben dem Kletterer applaudiert."},{t:4,s:"Jeder Kletterer braucht die richtige Ausrüstung."},{t:5,s:"Der Kletterer hat die Wand erfolgreich bewältigt."}]},
  "climbers": {label:"Kletterer",gender:"der",plural:"Kletterer", ex5:[{t:1,s:"Die Kletterer erreichten den Gipfel vor dem Mittag."},{t:2,s:"Erfahrene Kletterer tragen immer zusätzliches Wasser bei sich."},{t:3,s:"Der Berg ist bei vielen Kletterern sehr beliebt."},{t:4,s:"Die Kletterer sicherten sich gegenseitig am Seil."},{t:5,s:"Diese Kletterer trainieren jeden Tag."}]},
  "climbing": {label:"Klettern",gender:"das",plural:"—", ex5:[{t:1,s:"Klettern ist ein anstrengender Sport."},{t:2,s:"Die Preise steigen, und das Klettern der Inflation ist spürbar."},{t:3,s:"Wir waren am Wochenende beim Klettern."},{t:4,s:"Klettern erfordert viel Konzentration und Kraft."},{t:5,s:"Ich finde das Klettern in der Halle sehr entspannend."}]},
  "climbs": {label:"klettert",gender:"",plural:"—", ex5:[{t:1,s:"Er klettert jedes Wochenende auf den Berg."},{t:2,s:"Die Katze klettert auf den Baum, um sich zu verstecken."},{t:3,s:"Sie klettert auf die Leiter, um das Regal zu erreichen."},{t:4,s:"Der Junge klettert geschickt über den Zaun."},{t:5,s:"Er klettert regelmäßig in seiner Freizeit."}]},
  "clinch": {label:"sichern",gender:"",plural:"—", ex5:[{t:1,s:"Das Team konnte sich den Sieg sichern."},{t:2,s:"Sie haben den Geschäftsabschluss heute endlich sichern können."},{t:3,s:"Dieser Sieg hilft ihnen, einen Platz im Finale zu sichern."},{t:4,s:"Er wollte sich den ersten Platz sichern."},{t:5,s:"Wir müssen uns den Vertrag noch heute sichern."}]},
  "clinched": {label:"sicherte",gender:"",plural:"—", ex5:[{t:1,s:"Das Team sicherte sich mit dem letzten Tor die Meisterschaft."},{t:2,s:"Sie sicherten sich den Deal nach einem langen Treffen."},{t:3,s:"Er sicherte seine Faust vor Wut während der Debatte."},{t:4,s:"Sie sicherte sich den Sieg in der letzten Sekunde."},{t:5,s:"Die Firma sicherte sich den wichtigen Auftrag."}]},
  "clinching": {label:"sichernd",gender:"",plural:"—", ex5:[{t:1,s:"Sie sind dabei, den Deal durch einen festen Händedruck zu besiegeln."},{t:2,s:"Das Sichern des Meistertitels war sein lebenslanger Traum."},{t:3,s:"Nach Stunden der Debatte sind sie endlich beim Sichern einer Entscheidung."},{t:4,s:"Er ist gerade dabei, sich den Erfolg zu sichern."},{t:5,s:"Das Sichern dieser Position ist sehr wichtig für uns."}]},
  "cling": {label:"klammern",gender:"",plural:"—", ex5:[{t:1,s:"Das Baby klammert sich gerne an seine Mutter."},{t:2,s:"Nasse Kleidung klammert sich an die Haut."},{t:3,s:"Er versuchte, sich zur Sicherheit an das Seil zu klammern."},{t:4,s:"Das Kind klammert sich bei Angst an mich."},{t:5,s:"Man sollte sich nicht an die Vergangenheit klammern."}]},
  "clinging": {label:"klammernd",gender:"",plural:"—", ex5:[{t:1,s:"Das Affenbaby war sich an den Rücken der Mutter klammernd."},{t:2,s:"Er ist immer noch an die Hoffnung klammernd, dass sie zurückkehrt."},{t:3,s:"Das nasse Hemd war sich an seinen Körper klammernd."},{t:4,s:"Das Kind ist sich fest an meine Hand klammernd."},{t:5,s:"Sie ist sich noch immer an ihre alte Meinung klammernd."}]},
  "clingy": {label:"anhänglich",gender:"",plural:"—", ex5:[{t:1,s:"Das Kleinkind ist sehr anhänglich, wenn es Fremde trifft."},{t:2,s:"Sie trug ein eng anliegendes Kleid."},{t:3,s:"Ich mag keine anhänglichen Menschen in einer Beziehung."},{t:4,s:"Mein Hund ist sehr anhänglich."},{t:5,s:"Er ist ein eher anhänglicher Typ."}]},
  "clinic": {label:"Klinik",gender:"die",plural:"Kliniken", ex5:[{t:1,s:"Die Klinik wurde eröffnet."},{t:2,s:"Die Klinik ist sehr sauber."},{t:3,s:"Wir haben die Klinik besucht."},{t:4,s:"Sie arbeitet in einer kleinen Klinik."},{t:5,s:"Die Klinik hat einen guten Ruf."}]},
  "clinical": {label:"klinisch",gender:"",plural:"—", ex5:[{t:1,s:"Die Studie ist klinisch."},{t:2,s:"Der Tonfall ist klinisch kühl."},{t:3,s:"Wir haben einen klinischen Test durchgeführt."},{t:4,s:"Es gibt klinische Anzeichen für eine Besserung."},{t:5,s:"Die klinische Forschung ist sehr wichtig."}]},
  "clinically": {label:"klinisch",gender:"",plural:"—", ex5:[{t:1,s:"Das Medikament ist klinisch bewährt."},{t:2,s:"Sie betrachtet die Situation klinisch sachlich."},{t:3,s:"Der Raum war in einem klinisch weißen Stil dekoriert."},{t:4,s:"Er wurde klinisch untersucht."},{t:5,s:"Die Ergebnisse sind klinisch relevant."}]},
  "clinician": {label:"Kliniker",gender:"der",plural:"Kliniker", ex5:[{t:1,s:"Der Kliniker untersuchte den Patienten sorgfältig."},{t:2,s:"Ein guter Kliniker hört sich die Sorgen des Patienten an."},{t:3,s:"Sie arbeitet als leitende Klinikerin im Krankenhaus."},{t:4,s:"Der Kliniker hat viel Erfahrung."},{t:5,s:"Man sollte einen erfahrenen Kliniker fragen."}]},
