  "clinics": {label:"Klinik",gender:"die",plural:"Kliniken", ex5:[{t:1,s:"In dieser Nachbarschaft gibt es mehrere kleine Kliniken."},{t:2,s:"Viele Kliniken bieten kostenlose Gesundheitschecks an."},{t:3,s:"Sie arbeitet in einer der örtlichen Kliniken."},{t:4,s:"Die Klinik hat einen sehr guten Ruf in der Stadt."},{t:5,s:"Wir müssen für die Untersuchung in die Klinik fahren."}]},
  "clink": {label:"klingen",gender:"",plural:"—", ex5:[{t:1,s:"Lass uns die Gläser klingen lassen und feiern."},{t:2,s:"Ich hörte das Klingen von Münzen in seiner Tasche."},{t:3,s:"Die Gläser machten ein sanftes Klingen, als sie sich berührten."},{t:4,s:"Das Klingen der Gläser war überall im Raum zu hören."},{t:5,s:"Ein fröhliches Klingen erfüllte den festlichen Saal."}]},
