  "clipboard": {label:"Zwischenablage",gender:"die",plural:"Zwischenablagen", ex5:[{t:1,s:"Kopiere den Text einfach in die Zwischenablage."},{t:2,s:"Der Inhalt der Zwischenablage wurde gelöscht."},{t:3,s:"Ich habe das Bild in die Zwischenablage kopiert."},{t:4,s:"Die Daten befinden sich jetzt in der Zwischenablage."},{t:5,s:"Nutze die Zwischenablage, um den Text einzufügen."}]},
  "clipped": {label:"abschneiden",gender:"",plural:"—", ex5:[{t:1,s:"Er hat den Artikel aus der Zeitung abgeschnitten."},{t:2,s:"Die Hecken wurden vom Gärtner sauber abgeschnitten."},{t:3,s:"Sie hat sich eine Locke abgeschnitten."},{t:4,s:"Ich habe das Etikett von der Kleidung abgeschnitten."},{t:5,s:"Er hat die überstehenden Zweige abgeschnitten."}]},
  "clipper": {label:"Nagelknipser",gender:"der",plural:"Nagelknipser", ex5:[{t:1,s:"Er benutzte einen Nagelknipser, um seine Nägel zu kürzen."},{t:2,s:"Der Nagelknipser liegt im Badezimmerschrank."},{t:3,s:"Stelle sicher, dass der Nagelknipser sauber ist."},{t:4,s:"Ich habe meinen Nagelknipser verloren."},{t:5,s:"Dieser Nagelknipser funktioniert einwandfrei."}]},
  "clippers": {label:"Haarschneidemaschine",gender:"die",plural:"Haarschneidemaschinen", ex5:[{t:1,s:"Ich habe eine neue Haarschneidemaschine gekauft."},{t:2,s:"Der Friseur benutzte eine scharfe Haarschneidemaschine für den Bart."},{t:3,s:"Bitte reinige die Haarschneidemaschine nach dem Gebrauch."},{t:4,s:"Diese Haarschneidemaschine arbeitet sehr präzise."},{t:5,s:"Mit der Haarschneidemaschine geht das Schneiden schnell."}]},
