  "clips": {label:"Clip",gender:"der",plural:"Clips", ex5:[{t:1,s:"Ich habe Clips benutzt, um die Papiere zusammenzuhalten."},{t:2,s:"Ich habe mir online mehrere lustige Clips angesehen."},{t:3,s:"Sie benutzt Haarclips, um ihre Haare ordentlich zu halten."},{t:4,s:"Hast du die Clips für die Unterlagen gesehen?"},{t:5,s:"Der kurze Clip war sehr unterhaltsam."}]},
  "clique": {label:"Clique",gender:"die",plural:"Cliquen", ex5:[{t:1,s:"Eine kleine Clique bestimmte alle Entscheidungen in der Schule."},{t:2,s:"Sie fühlte sich von der beliebten Clique ausgeschlossen."},{t:3,s:"Die Clique im Büro saß beim Mittagessen immer zusammen."},{t:4,s:"Er gehört zu einer festen Clique."},{t:5,s:"Die Clique trifft sich jeden Freitagabend."}]},
  "cliques": {label:"Cliquen",gender:"die",plural:"Cliquen", ex5:[{t:1,s:"In der Schule gibt es oft verschiedene soziale Cliquen."},{t:2,s:"Es ist schwer, diesen exklusiven Cliquen beizutreten."},{t:3,s:"Sie bilden oft kleine Cliquen, die andere ignorieren."},{t:4,s:"Man sieht überall kleine Cliquen auf dem Pausenhof."},{t:5,s:"Diese Cliquen sind oft sehr verschlossen."}]},
  "cloak": {label:"Umhang",gender:"der",plural:"Umhänge", ex5:[{t:1,s:"Der Umhang wehte im Wind."},{t:2,s:"Der Umhang ist dunkel."},{t:3,s:"Wir trugen einen Umhang."},{t:4,s:"Sie legte ihren Umhang ab."},{t:5,s:"Er hüllte sich in seinen schweren Umhang."}]},
  "cloaked": {label:"verhüllt",gender:"",plural:"—", ex5:[{t:1,s:"Der Berg war in dichten Nebel verhüllt."},{t:2,s:"Der Fremde war in einen dunklen Mantel verhüllt."},{t:3,s:"Das Geheimnis ist in tiefes Schweigen verhüllt."},{t:4,s:"Die Stadt war vom Nebel verhüllt."},{t:5,s:"Er erschien, in einen Umhang verhüllt."}]},
  "cloaking": {label:"verhüllen",gender:"",plural:"—", ex5:[{t:1,s:"Der Berg war dabei, sich in dichten Nebel zu verhüllen."},{t:2,s:"Er versucht, seine wahren Absichten mit einem Lächeln zu verhüllen."},{t:3,s:"Der Wald war dabei, das kleine Dorf in Schatten zu verhüllen."},{t:4,s:"Die Wolken verhüllen die Sicht auf den Gipfel."},{t:5,s:"Er möchte seine Absichten vor uns verhüllen."}]},
