  "closeted": {label:"einschließen",gender:"",plural:"—", ex5:[{t:1,s:"Er hat sich zum Lernen in seinem Zimmer eingeschlossen."},{t:2,s:"Der Manager hat das Team besprochen, um den Plan zu diskutieren."},{t:3,s:"Sie hat ihr Geheimnis viele Jahre lang eingeschlossen."},{t:4,s:"Er schloss sich ein, um in Ruhe zu arbeiten."},{t:5,s:"Sie hat sich vor der Welt eingeschlossen."}]},
  "closets": {label:"Kleiderschränke",gender:"die",plural:"Kleiderschränke", ex5:[{t:1,s:"Ich muss meine Kleidung in den Kleiderschränken ordnen."},{t:2,s:"Das Haus hat zwei große Kleiderschränke im Schlafzimmer."},{t:3,s:"Wir fanden alte Kisten in den dunklen Kleiderschränken."},{t:4,s:"Die Kleiderschränke sind alle neu."},{t:5,s:"Er hat die Kleiderschränke komplett ausgeräumt."}]},
