  "coefficients": {label:"Koeffizienten",gender:"die",plural:"Koeffizienten", ex5:[{t:1,s:"Du musst die Koeffizienten in dieser algebraischen Gleichung finden."},{t:2,s:"Der Lehrer erklärte, wie man die Koeffizienten multipliziert."},{t:3,s:"Diese Zahlen repräsentieren die Koeffizienten der Variablen."},{t:4,s:"Die Koeffizienten bestimmen das Ergebnis der Gleichung."},{t:5,s:"Vergleiche die Koeffizienten der beiden Terme."}]},
  "coerce": {label:"nötigen",gender:"",plural:"—", ex5:[{t:1,s:"Sie versuchten, ihn zur Unterschrift zu nötigen."},{t:2,s:"Niemand kann sie dazu nötigen, zu lügen."},{t:3,s:"Er fühlte sich zu diesem Geschäft genötigt."},{t:4,s:"Man sollte niemanden zu etwas nötigen."},{t:5,s:"Er ließ sich nicht dazu nötigen, das zu sagen."}]},
