  "copyrights": {label:"Urheberrechte",gender:"",plural:"—", ex5:[{t:1,s:"Das Unternehmen besitzt die Urheberrechte an all diesen Bildern."},{t:2,s:"Sie müssen die Urheberrechte der ursprünglichen Schöpfer respektieren."},{t:3,s:"Er studiert die Gesetze bezüglich internationaler Urheberrechte."},{t:4,s:"Der Schutz von Urheberrechten ist weltweit wichtig."},{t:5,s:"Viele Unternehmen kämpfen um ihre Urheberrechte."}]},
  "coral": {label:"Koralle",gender:"die",plural:"Korallen", ex5:[{t:1,s:"Die Koralle schimmerte im klaren Wasser."},{t:2,s:"Diese Koralle hat eine leuchtend rosa Farbe."},{t:3,s:"Wir haben beim Tauchen eine wunderschöne Koralle gesehen."},{t:4,s:"Die Koralle ist ein empfindliches Lebewesen."},{t:5,s:"Viele Fische verstecken sich hinter der Koralle."}]},
  "corals": {label:"Korallen",gender:"die",plural:"Korallen", ex5:[{t:1,s:"Der Ozean ist voller bunter Korallen."},{t:2,s:"Taucher genießen es, bei den Korallen zu schwimmen."},{t:3,s:"Die globale Erwärmung schädigt weltweit viele Korallen."},{t:4,s:"Wir müssen die Korallen vor der Zerstörung bewahren."},{t:5,s:"Das Riff besteht aus tausenden verschiedenen Korallen."}]},
