  "cordial": {label:"herzlich",gender:"",plural:"—", ex5:[{t:1,s:"Sie führten ein sehr herzliches Gespräch."},{t:2,s:"Sie bereitete uns einen herzlichen Empfang."},{t:3,s:"Die beiden Politiker blieben in einem herzlichen Ton."},{t:4,s:"Wir wurden herzlich begrüßt."},{t:5,s:"Vielen Dank für die herzliche Aufnahme."}]},
  "cordiality": {label:"Herzlichkeit",gender:"die",plural:"Herzlichkeiten", ex5:[{t:1,s:"Sie wurden mit großer Herzlichkeit empfangen."},{t:2,s:"Ihre Herzlichkeit gab allen ein gutes Gefühl."},{t:3,s:"Das Treffen war von einer spürbaren Herzlichkeit geprägt."},{t:4,s:"Er begegnete ihr mit echter Herzlichkeit."},{t:5,s:"Die Herzlichkeit der Gastgeber war beeindruckend."}]},
  "cordially": {label:"herzlich",gender:"",plural:"—", ex5:[{t:1,s:"Sie wurden an der Tür herzlich willkommen geheißen."},{t:2,s:"Sie hat uns herzlich zum Abendessen eingeladen."},{t:3,s:"Er begrüßte die Gäste sehr herzlich."},{t:4,s:"Wir danken Ihnen herzlich für Ihre Hilfe."},{t:5,s:"Ich lade dich herzlich zu meiner Party ein."}]},
  "cordless": {label:"kabellos",gender:"",plural:"—", ex5:[{t:1,s:"Dieser kabellose Staubsauger ist sehr praktisch."},{t:2,s:"Ich benutze zu Hause am liebsten ein kabelloses Telefon."},{t:3,s:"Der kabellose Akkuschrauber erleichtert die Arbeit enorm."},{t:4,s:"Die kabellosen Kopfhörer haben einen guten Klang."},{t:5,s:"Wir brauchen eine kabellose Tastatur für den Computer."}]},
  "cordoba": {label:"Córdoba",gender:"",plural:"—", ex5:[{t:1,s:"Wir haben die wunderschöne Stadt Córdoba in Spanien besucht."},{t:2,s:"Die Geschichte von Córdoba ist sehr reich und interessant."},{t:3,s:"Viele Touristen spazieren gerne durch die Straßen von Córdoba."},{t:4,s:"Córdoba ist für seine beeindruckende Architektur bekannt."},{t:5,s:"Im Sommer wird es in Córdoba sehr heiß."}]},
  "cordon": {label:"Absperrung",gender:"die",plural:"Absperrungen", ex5:[{t:1,s:"Die Polizei hat eine Absperrung um das Gebäude errichtet."},{t:2,s:"Niemand darf die polizeiliche Absperrung passieren."},{t:3,s:"Sie durchbrachen die Absperrung, um näher heranzukommen."},{t:4,s:"Die Absperrung wurde wegen des Konzerts vergrößert."},{t:5,s:"Bitte bleiben Sie hinter der Absperrung."}]},
  "cords": {label:"Kabel",gender:"das",plural:"Kabel", ex5:[{t:1,s:"Bitte ziehen Sie die Kabel aus der Steckdose, bevor Sie gehen."},{t:2,s:"Er entwirrt die unordentlichen Kabel hinter dem Schreibtisch."},{t:3,s:"Die Lampe braucht längere Kabel, um die Steckdose zu erreichen."},{t:4,s:"Überall liegen Kabel auf dem Boden."},{t:5,s:"Ich habe die Kabel sauber verlegt."}]},
  "corduroy": {label:"Kord",gender:"der",plural:"—", ex5:[{t:1,s:"Er trug eine warme Hose aus Kord."},{t:2,s:"Die Kordjacke hatte eine weiche Textur."},{t:3,s:"Kord ist für seinen gerippten Stoff bekannt."},{t:4,s:"Ich mag die Haptik von Kord im Winter."},{t:5,s:"Kord ist ein sehr strapazierfähiges Material."}]},
  "core": {label:"Kern",gender:"der",plural:"Kerne", ex5:[{t:1,s:"Der Kern blieb fest."},{t:2,s:"Der Kern ist solide."},{t:3,s:"Wir haben den Kern erreicht."},{t:4,s:"Das ist der Kern des Problems."},{t:5,s:"Der Kern der Erde ist extrem heiß."}]},
  "cores": {label:"Kerne",gender:"die",plural:"Kerne", ex5:[{t:1,s:"Entfernen Sie die Apfelkerne, bevor Sie mit dem Backen beginnen."},{t:2,s:"Die Erde hat mehrere Schichten, darunter den inneren und äußeren Kern."},{t:3,s:"Diese Werte bilden die Kerne unserer Unternehmenskultur."},{t:4,s:"Ich habe die Kerne aus der Frucht genommen."},{t:5,s:"Moderne Prozessoren haben oft mehrere Kerne."}]},
  "corey": {label:"Corey",gender:"der",plural:"—", ex5:[{t:1,s:"Corey ist der schnellste Läufer in unserem Team."},{t:2,s:"Ich habe vorhin mit Corey über das Projekt gesprochen."},{t:3,s:"Corey hat heute vergessen, seine Hausaufgaben mitzubringen."},{t:4,s:"Corey kommt morgen zu Besuch."},{t:5,s:"Ich habe Corey schon lange nicht mehr gesehen."}]},
  "corgi": {label:"Corgi",gender:"der",plural:"Corgis", ex5:[{t:1,s:"Der Corgi hat sehr kurze Beine und ein süßes Gesicht."},{t:2,s:"Mein Nachbar besitzt einen freundlichen Corgi."},{t:3,s:"Corgis sind als sehr energiegeladene Hunde bekannt."},{t:4,s:"Ein Corgi spielt gerne im Garten."},{t:5,s:"Der Corgi ist eine sehr beliebte Hunderasse."}]},
  "coriander": {label:"Koriander",gender:"der",plural:"—", ex5:[{t:1,s:"Sie hat Koriandersamen für das Curry angeröstet."},{t:2,s:"Koriander hat einen warmen, nussigen Geschmack."},{t:3,s:"Er hat den Koriander zu Pulver gemahlen."},{t:4,s:"Frischer Koriander passt gut zu vielen Gerichten."},{t:5,s:"Ich mag den intensiven Duft von Koriander."}]},
  "corinth": {label:"Korinth",gender:"",plural:"—", ex5:[{t:1,s:"Wir haben im Unterricht viel über das antike Korinth gelernt."},{t:2,s:"Die Ruinen von Korinth sind ein beliebtes Reiseziel."},{t:3,s:"Er liest ein Buch, das in der Stadt Korinth spielt."},{t:4,s:"Korinth war in der Antike eine bedeutende Handelsstadt."},{t:5,s:"Wir planen einen Ausflug nach Korinth."}]},
  "corinthian": {label:"korinthisch",gender:"",plural:"—", ex5:[{t:1,s:"Das Gebäude besticht durch seine korinthischen Säulen."},{t:2,s:"Er hat die Geschichte der korinthischen Architektur studiert."},{t:3,s:"Das Design folgt einem klassischen korinthischen Stil."},{t:4,s:"Die korinthische Ordnung ist sehr kunstvoll verziert."},{t:5,s:"Wir haben die korinthischen Tempel besichtigt."}]},
  "corinthians": {label:"Korintherbrief",gender:"der",plural:"Korintherbriefe", ex5:[{t:1,s:"Wir haben im Gottesdienst einen Abschnitt aus dem Korintherbrief gelesen."},{t:2,s:"Viele Menschen finden Trost in den Versen aus dem Korintherbrief."},{t:3,s:"Weißt du, aus welchem Kapitel des Korintherbriefs das stammt?"},{t:4,s:"Der Korintherbrief ist ein wichtiger Teil des Neuen Testaments."},{t:5,s:"Ich lese gerade im Korintherbrief."}]},
