  "corkboard": {label:"Pinnwand",gender:"die",plural:"Pinnwände", ex5:[{t:1,s:"Ich habe den Zeitplan an die Pinnwand geheftet."},{t:2,s:"An ihrer Pinnwand hängen viele schöne Fotos."},{t:3,s:"Meine Pinnwand ist voll mit Notizen und Terminen."},{t:4,s:"Bitte hänge den Zettel an die Pinnwand."},{t:5,s:"Wir haben eine neue Pinnwand für das Büro gekauft."}]},
  "corkscrew": {label:"Korkenzieher",gender:"der",plural:"Korkenzieher", ex5:[{t:1,s:"Wo hast du den Korkenzieher hingelegt?"},{t:2,s:"Ich brauche einen Korkenzieher, um diese Weinflasche zu öffnen."},{t:3,s:"Dieser elektrische Korkenzieher arbeitet sehr schnell."},{t:4,s:"Hast du den Korkenzieher in der Besteckschublade gefunden?"},{t:5,s:"Der Korkenzieher liegt neben den Weingläsern."}]},
  "cormorant": {label:"Kormoran",gender:"der",plural:"Kormorane", ex5:[{t:1,s:"Ein Kormoran trocknete seine Flügel auf dem Felsen."},{t:2,s:"Der Kormoran tauchte tief nach Fischen."},{t:3,s:"Ein schwarzer Kormoran saß auf der Boje."},{t:4,s:"Kormorane sind sehr gute Schwimmer und Taucher."},{t:5,s:"Wir haben am See einen Kormoran beobachtet."}]},
  "corn": {label:"Mais",gender:"der",plural:"Maise", ex5:[{t:1,s:"Der Mais ist auf dem Feld gut gewachsen."},{t:2,s:"Dieser Mais schmeckt sehr süß."},{t:3,s:"Wir haben den Mais auf dem Grill zubereitet."},{t:4,s:"Im Sommer essen wir gerne frischen Mais."},{t:5,s:"Das Feld ist voller goldgelbem Mais."}]},
  "cornbread": {label:"Maisbrot",gender:"das",plural:"Maisbrote", ex5:[{t:1,s:"Sie hat zum Abendessen frisches Maisbrot gebacken."},{t:2,s:"Möchtest du ein Stück warmes Maisbrot haben?"},{t:3,s:"Dieses Rezept für Maisbrot ist der Liebling meiner Großmutter."},{t:4,s:"Wir servieren das Chili immer mit Maisbrot."},{t:5,s:"Das selbstgemachte Maisbrot schmeckt hervorragend."}]},
  "cornea": {label:"Hornhaut",gender:"die",plural:"Hornhäute", ex5:[{t:1,s:"Die Hornhaut schützt das Auge."},{t:2,s:"Ein Kratzer auf der Hornhaut ist schmerzhaft."},{t:3,s:"Der Arzt untersuchte ihre Hornhaut gründlich."},{t:4,s:"Die Hornhaut ist ein transparenter Teil des Auges."},{t:5,s:"Bei einer Entzündung der Hornhaut muss man zum Arzt."}]},
  "corneal": {label:"korneal",gender:"",plural:"—", ex5:[{t:1,s:"Der Arzt untersuchte die korneale Oberfläche seines Auges."},{t:2,s:"Eine korneale Verletzung kann sehr schmerzhaft sein."},{t:3,s:"Sie benötigt einen kornealen Eingriff zur Sehverbesserung."},{t:4,s:"Korneale Trübungen können das Sehvermögen beeinträchtigen."},{t:5,s:"Die korneale Heilung verläuft bei ihm sehr gut."}]},
