  "councillors": {label:"Ratsmitglieder",gender:"",plural:"Ratsmitglieder", ex5:[{t:1,s:"Die Ratsmitglieder diskutierten den neuen Park."},{t:2,s:"Viele Ratsmitglieder stimmten gegen das Gesetz."},{t:3,s:"Die Ratsmitglieder hören sich die Sorgen der Bürger an."},{t:4,s:"Die Ratsmitglieder treffen sich regelmäßig."},{t:5,s:"Alle Ratsmitglieder haben den Antrag unterzeichnet."}]},
  "councilman": {label:"Stadtrat",gender:"der",plural:"Stadträte", ex5:[{t:1,s:"Der Stadtrat versprach, den Park zu verbessern."},{t:2,s:"Wir schrieben dem Stadtrat wegen des Verkehrs."},{t:3,s:"Der Stadtrat besuchte gestern die Eröffnungsfeier."},{t:4,s:"Der Stadtrat kümmert sich um unsere Anliegen."},{t:5,s:"Ich habe den Stadtrat im Rathaus getroffen."}]},
