  "crater": {label:"Krater",gender:"der",plural:"Krater", ex5:[{t:1,s:"Der Vulkan hat einen tiefen Krater."},{t:2,s:"Der Mond ist von Kratern übersät."},{t:3,s:"Ein Meteorit hinterließ einen riesigen Krater."},{t:4,s:"Wir blickten in den Krater des Vulkans."},{t:5,s:"Der Krater ist wissenschaftlich sehr interessant."}]},
