  "damning": {label:"vernichtend",gender:"",plural:"—", ex5:[{t:1,s:"Der Bericht lieferte vernichtende Beweise gegen den Chef."},{t:2,s:"Sein Schweigen war ein vernichtendes Geständnis."},{t:3,s:"Es gab vernichtende Fotos von ihm am Tatort."},{t:4,s:"Das Urteil der Kritiker war absolut vernichtend."},{t:5,s:"Sie musste sich einer vernichtenden Kritik stellen."}]},
  "damp": {label:"feucht",gender:"",plural:"—", ex5:[{t:1,s:"Das Tuch ist noch ein bisschen feucht."},{t:2,s:"Der Keller in diesem alten Haus ist sehr feucht."},{t:3,s:"Wir haben den feuchten Boden gründlich gewischt."},{t:4,s:"Die feuchte Luft tut meiner Haut gut."},{t:5,s:"Nach dem Regen war das Gras noch feucht."}]},
