  "danville": {label:"Danville",gender:"",plural:"—", ex5:[{t:1,s:"Ich bin in einer kleinen Stadt namens Danville aufgewachsen."},{t:2,s:"Wir planen für nächsten Sommer einen Roadtrip nach Danville."},{t:3,s:"Danville ist für sein schönes historisches Viertel bekannt."},{t:4,s:"Danville ist ein ruhiger Ort zum Leben."},{t:5,s:"Wir haben Verwandte, die in Danville wohnen."}]},
  "dao": {label:"Dao",gender:"das",plural:"—", ex5:[{t:1,s:"Er folgt den Prinzipien des Dao in seinem täglichen Leben."},{t:2,s:"Das Buch erklärt die Philosophie des Dao."},{t:3,s:"Das eigene Dao zu finden, ist eine lebenslange Reise."},{t:4,s:"Viele Menschen suchen nach ihrem inneren Dao."},{t:5,s:"Das Verständnis des Dao erfordert viel Geduld."}]},
