  "deeds": {label:"Taten",gender:"die",plural:"—", ex5:[{t:1,s:"Er ist bekannt für seine guten Taten."},{t:2,s:"Deine Taten zeigen, wer du bist."},{t:3,s:"Der Held wurde für seine Taten geehrt."},{t:4,s:"Worte sind gut, aber Taten sind besser."},{t:5,s:"Seine guten Taten werden nie vergessen."}]},
  "deem": {label:"erachten",gender:"",plural:"—", ex5:[{t:1,s:"Sie erachten den Plan als zu riskant."},{t:2,s:"Sie wurde als die beste Kandidatin erachtet."},{t:3,s:"Er erachtete es für klug, zu warten."},{t:4,s:"Wir erachten diese Maßnahme als notwendig."},{t:5,s:"Das Gericht erachtet die Beweise als ausreichend."}]},
  "deemed": {label:"erachtet",gender:"",plural:"—", ex5:[{t:1,s:"Das Projekt wurde vom Chef als großer Erfolg erachtet."},{t:2,s:"Dieser Bereich wird für Kinder als unsicher erachtet."},{t:3,s:"Die Beweise wurden als unzureichend für einen Prozess erachtet."},{t:4,s:"Das Gebäude wurde als einsturzgefährdet erachtet."},{t:5,s:"Sein Verhalten wurde als unangemessen erachtet."}]},
  "deeming": {label:"erachtend",gender:"",plural:"—", ex5:[{t:1,s:"Der Richter ist dabei, die Beweise als unzureichend zu erachten."},{t:2,s:"Sie sind gerade dabei, das Projekt als großen Erfolg zu erachten."},{t:3,s:"Die Reise als unsicher erachtend, entschied er sich für die Absage."},{t:4,s:"Das Komitee ist dabei, den Plan als zu riskant zu erachten."},{t:5,s:"Wir sind dabei, die Lage als ernst zu erachten."}]},
  "deems": {label:"erachtet",gender:"",plural:"—", ex5:[{t:1,s:"Der Lehrer erachtet dieses Buch als geeignet für junge Schüler."},{t:2,s:"Er erachtet es für notwendig, den Bericht noch einmal zu prüfen."},{t:3,s:"Das Komitee erachtet den Plan als zu riskant für die Umsetzung."},{t:4,s:"Sie erachtet dies als eine gute Gelegenheit."},{t:5,s:"Er erachtet dieses Ergebnis als einen Erfolg."}]},
  "deep": {label:"tief",gender:"",plural:"—", ex5:[{t:1,s:"Der Brunnen ist tief."},{t:2,s:"Der See ist tief."},{t:3,s:"Wir haben ein tiefes Loch gegraben."},{t:4,s:"Ich atmete tief durch."},{t:5,s:"Das Wasser ist hier sehr tief."}]},
