  "defeated": {label:"besiegt",gender:"",plural:"—", ex5:[{t:1,s:"Das Team wurde besiegt."},{t:2,s:"Der Feind ist endgültig besiegt."},{t:3,s:"Sie haben ihren Rivalen besiegt."},{t:4,s:"Er fühlte sich völlig besiegt nach dem Spiel."},{t:5,s:"Wir haben den Gegner klar besiegt."}]},
  "defeating": {label:"besiegend",gender:"",plural:"—", ex5:[{t:1,s:"Das Team ist dabei, seine Rivalen im Finale zu besiegen."},{t:2,s:"Das Besiegen einer schwierigen Herausforderung gibt einem Stolz."},{t:3,s:"Er war erfolgreich, indem er alle Hindernisse auf seinem Weg besiegte."},{t:4,s:"Das Besiegen des Gegners erfordert viel Training."},{t:5,s:"Sie konzentriert sich auf das Besiegen ihrer eigenen Schwächen."}]},
