  "defect": {label:"Defekt",gender:"der",plural:"Defekte", ex5:[{t:1,s:"Ein Defekt ist aufgetreten."},{t:2,s:"Der Defekt ist nur geringfügig."},{t:3,s:"Wir haben einen Defekt an der Maschine gefunden."},{t:4,s:"Der Defekt wurde schnell behoben."},{t:5,s:"Aufgrund eines Defekts funktioniert das Gerät nicht."}]},
  "defected": {label:"übergelaufen",gender:"",plural:"—", ex5:[{t:1,s:"Der Athlet ist für ein besseres Training in ein anderes Land übergelaufen."},{t:2,s:"Er ist wegen einer Meinungsverschiedenheit von der Gruppe übergelaufen."},{t:3,s:"Mehrere Soldaten sind während des langen Krieges übergelaufen."},{t:4,s:"Der Spion ist zum Feind übergelaufen."},{t:5,s:"Sie ist zu einer anderen politischen Partei übergelaufen."}]},
  "defection": {label:"Überlaufen",gender:"das",plural:"—", ex5:[{t:1,s:"Das Überlaufen des Spions verursachte einen großen Skandal."},{t:2,s:"Er plante sein Überlaufen über mehrere Monate hinweg."},{t:3,s:"Die Regierung war durch das Überlaufen des Beamten beschämt."},{t:4,s:"Das Überlaufen kam für alle völlig unerwartet."},{t:5,s:"Nach dem Überlaufen änderte sich die politische Lage."}]},
  "defective": {label:"defekt",gender:"",plural:"—", ex5:[{t:1,s:"Ich habe das defekte Spielzeug für eine Rückerstattung zurückgegeben."},{t:2,s:"Die Firma hat alle defekten Produkte sofort zurückgerufen."},{t:3,s:"Dieses Teil ist defekt und muss ersetzt werden."},{t:4,s:"Das Gerät war leider schon bei der Lieferung defekt."},{t:5,s:"Wir haben das defekte Kabel ausgetauscht."}]},
  "defender": {label:"Verteidiger",gender:"der",plural:"Verteidiger", ex5:[{t:1,s:"Der Verteidiger blockte den Ball erfolgreich."},{t:2,s:"Unser Verteidiger ist heute in Bestform."},{t:3,s:"Die Fans jubelten dem Verteidiger zu."},{t:4,s:"Ein guter Verteidiger muss schnell reagieren können."},{t:5,s:"Der Verteidiger rettete das Spiel in letzter Sekunde."}]},
  "defenders": {label:"Verteidiger",gender:"die",plural:"Verteidiger", ex5:[{t:1,s:"Die Verteidiger spielten in diesem Spiel hervorragend."},{t:2,s:"Wir brauchen starke Verteidiger, um zu gewinnen."},{t:3,s:"Die Burg hatte viele Verteidiger auf den Mauern."},{t:4,s:"Alle Verteidiger müssen ihre Position halten."},{t:5,s:"Die Verteidiger haben heute ihre Aufgabe gut gemacht."}]},
  "defending": {label:"Verteidigung",gender:"die",plural:"Verteidigungen", ex5:[{t:1,s:"Das Team arbeitet an der Verteidigung seines Titels."},{t:2,s:"Er ist mit der Verteidigung seines Freundes beschäftigt."},{t:3,s:"Sie verbrachte die Nacht mit der Verteidigung ihrer Ideen."},{t:4,s:"Die Verteidigung des Tors ist heute besonders wichtig."},{t:5,s:"Bei der Verteidigung seiner Meinung blieb er ruhig."}]},
