  "deficits": {label:"Defizite",gender:"die",plural:"—", ex5:[{t:1,s:"Das Unternehmen versucht, seine Budgetdefizite zu reduzieren."},{t:2,s:"Langfristige Defizite können die nationale Wirtschaft schädigen."},{t:3,s:"Sie sahen sich dieses Jahr mit massiven finanziellen Defiziten konfrontiert."},{t:4,s:"Diese Defizite sind besorgniserregend."},{t:5,s:"Die Regierung hat mehrere Defizite."}]},
  "defied": {label:"trotzte",gender:"",plural:"—", ex5:[{t:1,s:"Der tapfere Soldat trotzte den Befehlen des Feindes."},{t:2,s:"Sie trotzte allen Erwartungen und gewann das Rennen."},{t:3,s:"Er trotzte der Schwere der Situation mit einem Witz."},{t:4,s:"Das Kind trotzte seinen Eltern."},{t:5,s:"Sie trotzten den Regeln."}]},
