  "deus": {label:"Deus",gender:"der",plural:"Dei", ex5:[{t:1,s:"In der Literatur löst der Deus ex machina unlösbare Probleme."},{t:2,s:"Das Konzept eines Deus ist zentral für viele Religionen."},{t:3,s:"Er sprach von einem Deus als einer Naturgewalt."},{t:4,s:"Der Deus wird in vielen Mythen verehrt."},{t:5,s:"Philosophen diskutieren oft über den Deus."}]},
  "deuterium": {label:"Deuterium",gender:"das",plural:"—", ex5:[{t:1,s:"Deuterium wird oft als schwerer Wasserstoff bezeichnet."},{t:2,s:"Wissenschaftler untersuchen Deuterium, um Kernfusionsprozesse zu verstehen."},{t:3,s:"Das Meer enthält eine beachtliche Menge an Deuterium."},{t:4,s:"Deuterium ist ein wichtiges Isotop."},{t:5,s:"Man kann Deuterium aus Wasser gewinnen."}]},
  "deuteronomy": {label:"Deuteronomium",gender:"das",plural:"—", ex5:[{t:1,s:"Wir haben heute eine Passage aus dem Deuteronomium gelesen."},{t:2,s:"Das Deuteronomium ist das fünfte Buch des Alten Testaments."},{t:3,s:"Er verbrachte den Morgen damit, Verse im Deuteronomium zu studieren."},{t:4,s:"Im Deuteronomium stehen viele Gesetze."},{t:5,s:"Das Deuteronomium wird auch als das fünfte Buch Mose bezeichnet."}]},
  "deutsch": {label:"Deutsch",gender:"das",plural:"—", ex5:[{t:1,s:"Er lernt zurzeit Deutsch an der Volkshochschule."},{t:2,s:"Viele Wörter im Deutschen haben Ähnlichkeiten mit dem Englischen."},{t:3,s:"Sie ist nach Berlin gezogen, um ihr Deutsch zu verbessern."},{t:4,s:"Deutsch ist eine sehr interessante Sprache."},{t:5,s:"Ich verstehe noch nicht alles, wenn man Deutsch spricht."}]},
  "deutsche": {label:"deutsch",gender:"",plural:"—", ex5:[{t:1,s:"Sie arbeitet bei einer großen deutschen Bank."},{t:2,s:"Viele deutsche Unternehmen investieren in neue Technologien."},{t:3,s:"Ich habe einen Artikel über den deutschen Markt gelesen."},{t:4,s:"Das deutsche Essen schmeckt mir sehr gut."},{t:5,s:"Er hat viele deutsche Freunde in Berlin."}]},
  "deutschland": {label:"Deutschland",gender:"das",plural:"—", ex5:[{t:1,s:"Viele Touristen besuchen im Sommer gerne Deutschland."},{t:2,s:"Er plant nächsten Monat eine lange Reise durch Deutschland."},{t:3,s:"Deutschland ist für seine Geschichte und schönen Schlösser bekannt."},{t:4,s:"Ich lebe sehr gerne in Deutschland."},{t:5,s:"Deutschland hat viele verschiedene Bundesländer."}]},
  "devaluation": {label:"Abwertung",gender:"die",plural:"Abwertungen", ex5:[{t:1,s:"Die Abwertung der Währung hat die lokale Wirtschaft beeinflusst."},{t:2,s:"Sie kündigten eine plötzliche Abwertung des Dollars an."},{t:3,s:"Die Abwertung ihrer Arbeit hat sie traurig gemacht."},{t:4,s:"Eine wirtschaftliche Abwertung ist oft ein komplexer Prozess."},{t:5,s:"Die Abwertung des Vermögens war für die Firma ein Schock."}]},
  "devalue": {label:"abwerten",gender:"",plural:"—", ex5:[{t:1,s:"Die Regierung entschied, die Währung abzuwerten, um Exporte zu fördern."},{t:2,s:"Werte deine eigene Leistung nicht ab, nur weil du nicht gewonnen hast."},{t:3,s:"Ständige Kritik kann das Selbstwertgefühl eines Menschen abwerten."},{t:4,s:"Man sollte die Arbeit anderer nicht einfach abwerten."},{t:5,s:"Er versucht, die Bedeutung dieses Ereignisses abzuwerten."}]},
  "devalued": {label:"abgewertet",gender:"",plural:"—", ex5:[{t:1,s:"Die Regierung hat die Währung abgewertet, um die Exporte zu steigern."},{t:2,s:"Viele fühlten sich durch die neue Politik in ihrer Arbeit abgewertet."},{t:3,s:"Das Unternehmen hat seine Vermögenswerte nach dem Börsencrash abgewertet."},{t:4,s:"Seine Leistung wurde leider völlig abgewertet."},{t:5,s:"Der Euro wurde gegenüber dem Dollar abgewertet."}]},
  "devastate": {label:"verwüsten",gender:"",plural:"—", ex5:[{t:1,s:"Das Erdbeben wird das kleine Küstendorf verwüsten."},{t:2,s:"Die Nachricht von seinem Tod wird die ganze Familie erschüttern."},{t:3,s:"Starke Stürme können die Ernte vor Ort verwüsten."},{t:4,s:"Die Flut droht, das ganze Dorf zu verwüsten."},{t:5,s:"Der Krieg kann ganze Landstriche verwüsten."}]},
  "devastated": {label:"am Boden zerstört",gender:"",plural:"—", ex5:[{t:1,s:"Sie war am Boden zerstört, als sie die schlechte Nachricht hörte."},{t:2,s:"Der Sturm hat die kleine Stadt völlig zerstört."},{t:3,s:"Er war am Boden zerstört, nachdem er sein Lieblingsspielzeug verloren hatte."},{t:4,s:"Nach dem Unfall war die Familie völlig am Boden zerstört."},{t:5,s:"Die ganze Region war nach der Naturkatastrophe am Boden zerstört."}]},
  "developments": {label:"Entwicklungen",gender:"die",plural:"Entwicklungen", ex5:[{t:1,s:"Wir beobachten die neuesten Entwicklungen in der Technologie."},{t:2,s:"Aktuelle Entwicklungen in der Stadt haben den Nahverkehr verbessert."},{t:3,s:"Ich verfolge die politischen Entwicklungen in meinem Land."},{t:4,s:"Es gibt spannende Entwicklungen bei diesem Projekt."},{t:5,s:"Man muss die Entwicklungen genau im Auge behalten."}]},
  "develops": {label:"entwickeln",gender:"",plural:"—", ex5:[{t:1,s:"Die Firma entwickelt neue Software."},{t:2,s:"Er entwickelt seine Fähigkeiten durch tägliches Üben."},{t:3,s:"Die Geschichte entwickelt sich langsam, ist aber lohnend."},{t:4,s:"Sie entwickelt ein neues Konzept für das Projekt."},{t:5,s:"Man muss Geduld haben, während man sich weiterentwickelt."}]},
  "deviant": {label:"abweichend",gender:"",plural:"—", ex5:[{t:1,s:"Die Schule hat eine strenge Richtlinie gegen abweichendes Verhalten."},{t:2,s:"Soziologen untersuchen die Ursachen von abweichenden Handlungen in der Gesellschaft."},{t:3,s:"Seine abweichenden Methoden zur Problemlösung überraschten seine Kollegen."},{t:4,s:"Ein abweichendes Ergebnis erfordert eine neue Analyse."},{t:5,s:"Man sollte abweichendes Verhalten frühzeitig thematisieren."}]},
  "deviate": {label:"abweichen",gender:"",plural:"—", ex5:[{t:1,s:"Weichen Sie nicht vom Plan ab."},{t:2,s:"Die Straße weicht hier nach links ab."},{t:3,s:"Seine Antwort wich von der Wahrheit ab."},{t:4,s:"Wir dürfen nicht vom Thema abweichen."},{t:5,s:"Die Ergebnisse weichen deutlich von der Norm ab."}]},
