  "diffraction": {label:"Beugung",gender:"die",plural:"Beugungen", ex5:[{t:1,s:"Die Beugung des Lichts erklärt, warum Schatten nicht scharf sind."},{t:2,s:"Wir haben im Physikunterricht über die Beugung von Schall gelernt."},{t:3,s:"Die Röntgenbeugung wird zur Untersuchung von Kristallstrukturen genutzt."},{t:4,s:"Die Beugung ist ein typisches Wellenphänomen."},{t:5,s:"Licht zeigt an Hindernissen eine deutliche Beugung."}]},
  "diffuse": {label:"diffus",gender:"",plural:"—", ex5:[{t:1,s:"Das Licht war diffus und schuf eine sanfte Atmosphäre."},{t:2,s:"Informationen können sich diffus in sozialen Medien verbreiten."},{t:3,s:"Der Duft des Parfüms begann sich diffus im Raum zu verteilen."},{t:4,s:"Ein diffuses Licht fiel durch das Fenster."},{t:5,s:"Das Gerücht verbreitete sich diffus unter den Leuten."}]},
  "diffused": {label:"diffundiert",gender:"",plural:"—", ex5:[{t:1,s:"Das Licht wurde durch die dünnen Vorhänge diffundiert."},{t:2,s:"Der Geruch von frischem Brot ist durch das Haus diffundiert."},{t:3,s:"Seine Wut ist langsam in ruhiges Verständnis diffundiert."},{t:4,s:"Der Duft ist in den ganzen Raum diffundiert."},{t:5,s:"Das Licht ist weich diffundiert worden."}]},
  "diffuser": {label:"Diffusor",gender:"der",plural:"Diffusoren", ex5:[{t:1,s:"Ich habe Lavendelöl in meinen elektrischen Diffusor gegeben."},{t:2,s:"Dieser Raum-Diffusor lässt das Zimmer wunderbar duften."},{t:3,s:"Der Diffusor hilft, den Duft gleichmäßig zu verteilen."},{t:4,s:"Ein Diffusor ist praktisch für ätherische Öle."},{t:5,s:"Der Diffusor steht auf dem Regal."}]},
  "diffusion": {label:"Diffusion",gender:"die",plural:"Diffusionen", ex5:[{t:1,s:"Die Diffusion neuer Ideen geschieht online sehr schnell."},{t:2,s:"Wir haben die Diffusion von Gasen im Wissenschaftsunterricht gelernt."},{t:3,s:"Die Diffusion von Licht erzeugt eine sanfte Atmosphäre."},{t:4,s:"Diffusion ist ein physikalischer Prozess."},{t:5,s:"Die Diffusion sorgt für eine gleichmäßige Verteilung."}]},
  "digit": {label:"Ziffer",gender:"die",plural:"Ziffern", ex5:[{t:1,s:"Der Code besteht aus einer vierstelligen Zahl."},{t:2,s:"Können Sie die letzte Ziffer der Telefonnummer aufschreiben?"},{t:3,s:"Er ist gut in Mathe und arbeitet mit jeder einzelnen Ziffer."},{t:4,s:"Die Ziffer wurde falsch eingetragen."},{t:5,s:"Diese Zahl hat fünf Ziffern."}]},
  "digital": {label:"digital",gender:"",plural:"—", ex5:[{t:1,s:"Die Welt ist digital."},{t:2,s:"Die Uhr ist digital."},{t:3,s:"Wir sind auf digitale Medien umgestiegen."},{t:4,s:"Das Zeitalter ist digital."},{t:5,s:"Alles läuft heute digital ab."}]},
