  "dinosaur": {label:"Dinosaurier",gender:"der",plural:"Dinosaurier", ex5:[{t:1,s:"Der Dinosaurier brüllte laut."},{t:2,s:"Dieser Dinosaurier ist wirklich riesig."},{t:3,s:"Wir haben uns ein Modell von einem Dinosaurier angesehen."},{t:4,s:"Mein Sohn spielt gerne mit einem Dinosaurier."},{t:5,s:"Der Dinosaurier lebte vor sehr langer Zeit."}]},
  "dinosaurs": {label:"Dinosaurier",gender:"der",plural:"Dinosaurier", ex5:[{t:1,s:"Ich lese sehr gerne Bücher über Dinosaurier."},{t:2,s:"Dinosaurier lebten vor Millionen von Jahren auf der Erde."},{t:3,s:"Wir haben im Museum viele Knochen von Dinosauriern gesehen."},{t:4,s:"Es gibt viele verschiedene Arten von Dinosauriern."},{t:5,s:"Dinosaurier faszinieren Kinder auf der ganzen Welt."}]},
