  "disaster": {label:"Katastrophe",gender:"die",plural:"Katastrophen", ex5:[{t:1,s:"Eine Katastrophe ist eingetreten."},{t:2,s:"Das Ausmaß der Katastrophe ist riesig."},{t:3,s:"Wir haben die Katastrophe überlebt."},{t:4,s:"Man muss auf eine Katastrophe vorbereitet sein."},{t:5,s:"Das war eine absolute Katastrophe."}]},
  "disasters": {label:"Katastrophen",gender:"die",plural:"Katastrophen", ex5:[{t:1,s:"Wir müssen uns auf Naturkatastrophen wie Erdbeben vorbereiten."},{t:2,s:"Die Wohltätigkeitsorganisation hilft den Betroffenen von jüngsten Katastrophen."},{t:3,s:"Viele Katastrophen können durch bessere Planung verhindert werden."},{t:4,s:"Die Nachrichten berichten oft über Katastrophen weltweit."},{t:5,s:"Wir müssen lernen, mit verschiedenen Katastrophen umzugehen."}]},
