  "displeased": {label:"unzufrieden",gender:"",plural:"—", ex5:[{t:1,s:"Der Lehrer war mit unserem lauten Verhalten unzufrieden."},{t:2,s:"Er sah unzufrieden aus, als er die schlechte Nachricht hörte."},{t:3,s:"Mein Chef war unzufrieden, dass der Bericht zu spät kam."},{t:4,s:"Sie äußerte sich unzufrieden über das Ergebnis."},{t:5,s:"Ich bin mit dem Service heute sehr unzufrieden."}]},
  "displeasure": {label:"das Missfallen",gender:"das",plural:"—", ex5:[{t:1,s:"Er drückte sein Missfallen über den schlechten Service aus."},{t:2,s:"Sie zeigte ihr Missfallen, indem sie den ganzen Abend schwieg."},{t:3,s:"Der Chef machte sein Missfallen während der Sitzung deutlich."},{t:4,s:"Er konnte sein Missfallen nicht verbergen."},{t:5,s:"Das Missfallen der Kunden war deutlich spürbar."}]},
