  "disposal": {label:"die Entsorgung",gender:"die",plural:"Entsorgungen", ex5:[{t:1,s:"Die Entsorgung ist kostspielig."},{t:2,s:"Die Entsorgung erfolgt sicher."},{t:3,s:"Wir haben die Entsorgung organisiert."},{t:4,s:"Die Entsorgung von Abfall ist streng geregelt."},{t:5,s:"Er kümmert sich um die Entsorgung der alten Möbel."}]},
  "dispose": {label:"entsorgen",gender:"",plural:"—", ex5:[{t:1,s:"Wir entsorgen den Müll."},{t:2,s:"Die Fabrik entsorgt es gerade."},{t:3,s:"Wir müssen den Abfall ordnungsgemäß entsorgen."},{t:4,s:"Er entsorgt seinen alten Müll in der Tonne."},{t:5,s:"Man kann hier keine gefährlichen Stoffe entsorgen."}]},
