  "dispositions": {label:"Veranlagung",gender:"die",plural:"Veranlagungen", ex5:[{t:1,s:"Die beiden Brüder haben eine sehr unterschiedliche Veranlagung."},{t:2,s:"Sie hat eine fröhliche Veranlagung, die alle glücklich macht."},{t:3,s:"Die Lehrerin versteht die verschiedenen Veranlagungen ihrer Schüler."},{t:4,s:"Er hat eine künstlerische Veranlagung."},{t:5,s:"Das Kind zeigt eine ruhige Veranlagung."}]},
  "dispossess": {label:"enteignen",gender:"",plural:"—", ex5:[{t:1,s:"Der Krieg hat viele Familien enteignet."},{t:2,s:"Sie wurden von ihrem Land enteignet."},{t:3,s:"Das Gesetz könnte die Mieter enteignen."},{t:4,s:"Der Staat musste die Eigentümer enteignen."},{t:5,s:"Man darf niemanden ohne Grund enteignen."}]},
  "dispossessed": {label:"enteignet",gender:"",plural:"—", ex5:[{t:1,s:"Der Krieg hat Tausende von Menschen enteignet."},{t:2,s:"Sie wurden durch das neue Gesetz von ihrem Land enteignet."},{t:3,s:"Der König hat die Adligen ihrer Titel enteignet."},{t:4,s:"Die enteigneten Familien kämpfen um ihr Recht."},{t:5,s:"Viele wurden in dieser Zeit enteignet."}]},
  "disproportionate": {label:"unverhältnismäßig",gender:"",plural:"—", ex5:[{t:1,s:"Die Strafe war unverhältnismäßig zum Verbrechen."},{t:2,s:"Sie geben eine unverhältnismäßig große Summe für Luxusgüter aus."},{t:3,s:"Es gibt eine unverhältnismäßig hohe Anzahl von Schülern in dem kleinen Raum."},{t:4,s:"Das Risiko ist unverhältnismäßig hoch."},{t:5,s:"Die Kosten sind völlig unverhältnismäßig."}]},
  "disproportionately": {label:"unverhältnismäßig",gender:"",plural:"—", ex5:[{t:1,s:"Die Armen sind unverhältnismäßig stark von den neuen Steuern betroffen."},{t:2,s:"Dieses kleine Zimmer hat ein unverhältnismäßig großes Fenster."},{t:3,s:"Die Firma gibt unverhältnismäßig viel Geld für Marketing aus."},{t:4,s:"Er wurde unverhältnismäßig hart bestraft."},{t:5,s:"Der Aufwand ist unverhältnismäßig groß."}]},
