  "disputation": {label:"Disputation",gender:"die",plural:"Disputationen", ex5:[{t:1,s:"Die lebhafte Disputation dauerte bis spät in die Nacht."},{t:2,s:"Ihre akademische Disputation basierte auf fundierter Forschung."},{t:3,s:"Er vermied jede öffentliche Disputation mit seinem Gegner."},{t:4,s:"Die Disputation führte zu keinem Ergebnis."},{t:5,s:"Es gab eine lange Disputation über das Thema."}]},
  "disputatious": {label:"streitsüchtig",gender:"",plural:"—", ex5:[{t:1,s:"Er hat eine streitsüchtige Natur."},{t:2,s:"Die streitsüchtige Menge diskutierte stundenlang."},{t:3,s:"Ein streitsüchtiger Ton ruiniert das Gespräch."},{t:4,s:"Sie ist sehr streitsüchtig bei solchen Themen."},{t:5,s:"Er wirkt oft streitsüchtig."}]},
  "dispute": {label:"Streit",gender:"der",plural:"Streite", ex5:[{t:1,s:"Ein Streit ist ausgebrochen."},{t:2,s:"Der Streit ist bitter."},{t:3,s:"Wir haben den Streit beigelegt."},{t:4,s:"Es gibt einen Streit zwischen den Nachbarn."},{t:5,s:"Der Streit führte zu einer Trennung."}]},
  "disputed": {label:"umstritten",gender:"",plural:"—", ex5:[{t:1,s:"Die Grenze zwischen den Ländern ist seit Jahren umstritten."},{t:2,s:"Die Entscheidung des Schiedsrichters war sehr umstritten."},{t:3,s:"Der Besitz des Grundstücks ist weiterhin umstritten."},{t:4,s:"Das ist ein sehr umstrittenes Thema."},{t:5,s:"Seine Theorie bleibt in der Fachwelt umstritten."}]},
  "disputes": {label:"Streitigkeiten",gender:"die",plural:"Streitigkeiten", ex5:[{t:1,s:"Es gab viele Streitigkeiten über die neuen Regeln."},{t:2,s:"Sie hatten familiäre Streitigkeiten wegen des Erbes."},{t:3,s:"Die Firma versucht, Streitigkeiten mit Kunden schnell zu klären."},{t:4,s:"Kleine Streitigkeiten kommen in jeder Beziehung vor."},{t:5,s:"Die Streitigkeiten dauerten den ganzen Abend an."}]},
