  "disqualified": {label:"disqualifiziert",gender:"",plural:"—", ex5:[{t:1,s:"Er wurde wegen eines Fehlstarts vom Rennen disqualifiziert."},{t:2,s:"Der Athlet wurde wegen Dopings disqualifiziert."},{t:3,s:"Ihr unangemessenes Verhalten hat sie vom Wettbewerb disqualifiziert."},{t:4,s:"Er wurde aufgrund eines technischen Fehlers disqualifiziert."},{t:5,s:"Das gesamte Team wurde wegen Regelverstößen disqualifiziert."}]},
