  "disqualifying": {label:"disqualifizierend",gender:"",plural:"—", ex5:[{t:1,s:"Der Schiedsrichter ist dabei, den Spieler wegen eines Fouls zu disqualifizieren."},{t:2,s:"Sie sind gerade dabei, Teilnehmer zu disqualifizieren, die gegen die Regeln verstoßen haben."},{t:3,s:"Das Komitee ist dabei, den Kandidaten wegen Lügens zu disqualifizieren."},{t:4,s:"Die Entscheidung wirkt auf viele sehr disqualifizierend."},{t:5,s:"Das Gremium ist damit beschäftigt, die unfairen Sportler zu disqualifizieren."}]},
  "disquiet": {label:"Unruhe",gender:"die",plural:"—", ex5:[{t:1,s:"Die Nachricht verursachte weitverbreitete Unruhe."},{t:2,s:"Eine vage Unruhe legte sich über die Stadt."},{t:3,s:"Sein Schweigen erfüllte sie mit Unruhe."},{t:4,s:"Die politische Lage sorgt für große Unruhe."},{t:5,s:"In der Bevölkerung herrscht Unruhe."}]},
  "disregard": {label:"missachten",gender:"",plural:"—", ex5:[{t:1,s:"Er entschied sich, die Warnung zu missachten."},{t:2,s:"Bitte missachte meine letzte Nachricht."},{t:3,s:"Sie missachtete den unhöflichen Kommentar."},{t:4,s:"Man sollte die Sicherheitsregeln nicht missachten."},{t:5,s:"Er hat die Anweisungen des Lehrers missachtet."}]},
  "disregarded": {label:"missachtet",gender:"",plural:"—", ex5:[{t:1,s:"Er hat die Warnung missachtet und ist ins Wasser gegangen."},{t:2,s:"Der Richter hat die Aussage des Zeugen missachtet."},{t:3,s:"Sie hatte das Gefühl, dass ihre Meinung missachtet wurde."},{t:4,s:"Sein Vorschlag wurde bei der Besprechung missachtet."},{t:5,s:"Die Bedenken der Anwohner wurden völlig missachtet."}]},
