  "disregards": {label:"missachten",gender:"",plural:"—", ex5:[{t:1,s:"Er missachtet oft die Regeln, wenn er es eilig hat."},{t:2,s:"Sie missachtet seine negativen Kommentare konsequent."},{t:3,s:"Der Wissenschaftler missachtet die fehlerhaften Daten."},{t:4,s:"Man sollte die Verkehrszeichen nicht missachten."},{t:5,s:"Er missachtet meine Meinung ständig."}]},
  "disrepair": {label:"Verfall",gender:"der",plural:"Verfälle", ex5:[{t:1,s:"Das alte Gebäude befindet sich in einem Zustand des Verfalls."},{t:2,s:"Der Verfall der Brücke ist für alle sichtbar."},{t:3,s:"Jahrelange Vernachlässigung führte zum Verfall des Hauses."},{t:4,s:"Der Verfall der historischen Mauer muss gestoppt werden."},{t:5,s:"Das Dorf ist vom Verfall bedroht."}]},
  "disrepute": {label:"Verruf",gender:"der",plural:"—", ex5:[{t:1,s:"Der Skandal brachte die Firma in Verruf."},{t:2,s:"Seine Handlungen brachten den Familiennamen in Verruf."},{t:3,s:"Der Politiker geriet nach dem Skandal in Verruf."},{t:4,s:"Man sollte sich nicht in Verruf bringen."},{t:5,s:"Die Sache ist völlig in Verruf geraten."}]},
