  "disrespected": {label:"respektlos behandelt",gender:"",plural:"—", ex5:[{t:1,s:"Er fühlte sich respektlos behandelt, als sein Chef ihn ignorierte."},{t:2,s:"Sie wurde von dem unhöflichen Kunden respektlos behandelt."},{t:3,s:"Die Schüler fühlten sich durch die harten Worte respektlos behandelt."},{t:4,s:"Niemand möchte respektlos behandelt werden."},{t:5,s:"Er wurde im Meeting respektlos behandelt."}]},
  "disrespectful": {label:"respektlos",gender:"",plural:"—", ex5:[{t:1,s:"Es ist respektlos, während des Unterrichts zu reden."},{t:2,s:"Sie entschuldigte sich für ihre respektlose Bemerkung."},{t:3,s:"Sein Verhalten gegenüber den Eltern war sehr respektlos."},{t:4,s:"Das war eine respektlose Antwort."},{t:5,s:"Er war sehr respektlos zu seinen Kollegen."}]},
  "disrespecting": {label:"respektlos behandeln",gender:"",plural:"—", ex5:[{t:1,s:"Hör auf, deine Älteren respektlos zu behandeln."},{t:2,s:"Er wurde entlassen, weil er seinen Chef respektlos behandelt hat."},{t:3,s:"Sie fühlte, dass er sie respektlos behandelte."},{t:4,s:"Man darf niemanden respektlos behandeln."},{t:5,s:"Er hat seine Freunde respektlos behandelt."}]},
  "disrupt": {label:"stören",gender:"",plural:"—", ex5:[{t:1,s:"Stürme stören den Reiseverkehr."},{t:2,s:"Der Streik stört den Ablauf der Arbeit."},{t:3,s:"Wir stören die gewohnte Routine."},{t:4,s:"Laute Geräusche stören die Konzentration."},{t:5,s:"Plötzliche Änderungen stören den Zeitplan."}]},
  "disrupted": {label:"gestört",gender:"",plural:"—", ex5:[{t:1,s:"Der Sturm hat den Verkehr gestört."},{t:2,s:"Seine Ankunft hat das Meeting gestört."},{t:3,s:"Laute Geräusche haben meinen Schlaf gestört."},{t:4,s:"Der Ablauf wurde durch ein Problem gestört."},{t:5,s:"Die Funkverbindung wurde gestört."}]},
  "disrupting": {label:"störend",gender:"",plural:"—", ex5:[{t:1,s:"Der Lärm draußen wirkt störend auf meine Konzentration."},{t:2,s:"Der starke Schneefall ist störend für den gesamten Verkehr."},{t:3,s:"Bitte unterlass das störende Reden im Unterricht."},{t:4,s:"Das Telefonklingeln ist störend bei der Arbeit."},{t:5,s:"Dieser störende Ton macht mich nervös."}]},
