  "dna": {label:"DNA",gender:"die",plural:"—", ex5:[{t:1,s:"Wissenschaftler untersuchen die DNA, um Krankheiten zu verstehen."},{t:2,s:"Jedes Lebewesen hat eine einzigartige DNA."},{t:3,s:"Der DNA-Test hat die Verwandtschaft bestätigt."},{t:4,s:"Die DNA speichert unsere genetischen Informationen."},{t:5,s:"Man kann die DNA in jeder Zelle finden."}]},
  "dnd": {label:"Nicht-stören-Modus",gender:"der",plural:"—", ex5:[{t:1,s:"Ich habe mein Handy während des Meetings in den Nicht-stören-Modus geschaltet."},{t:2,s:"Bitte aktiviere den Nicht-stören-Modus, wenn du schläfst."},{t:3,s:"Mein Tablet ist im Nicht-stören-Modus, damit ich ungestört lesen kann."},{t:4,s:"Der Nicht-stören-Modus ist sehr nützlich für die Konzentration."},{t:5,s:"Vergiss nicht, den Nicht-stören-Modus einzuschalten."}]},
