  "donates": {label:"spendet",gender:"",plural:"—", ex5:[{t:1,s:"Er spendet jedes Jahr seine alte Kleidung für einen guten Zweck."},{t:2,s:"Meine Mutter spendet regelmäßig Geld an das Tierheim."},{t:3,s:"Sie spendet Blut, um kranken Menschen zu helfen."},{t:4,s:"Er spendet einen Teil seines Gehalts an die Umweltstiftung."},{t:5,s:"Die Organisation spendet Lebensmittel an Obdachlose."}]},
  "donating": {label:"spendend",gender:"",plural:"—", ex5:[{t:1,s:"Sie ist gerade dabei, ihre alten Kleider zu spenden."},{t:2,s:"Wir sind dabei, Geld für das örtliche Krankenhaus zu spenden."},{t:3,s:"Ist er heute Blut am Spenden?"},{t:4,s:"Die Leute sind sehr großzügig beim Spenden."},{t:5,s:"Er verbringt seine Zeit damit, für gute Zwecke zu spenden."}]},
  "donation": {label:"Spende",gender:"die",plural:"Spenden", ex5:[{t:1,s:"Die Spende ist heute angekommen."},{t:2,s:"Die Spende war sehr großzügig."},{t:3,s:"Wir haben eine Spende getätigt."},{t:4,s:"Jede Spende hilft den Bedürftigen sehr."},{t:5,s:"Danke für deine freundliche Spende."}]},
