  "earthquake": {label:"Erdbeben",gender:"das",plural:"Erdbeben", ex5:[{t:1,s:"Das Erdbeben ereignete sich am frühen Morgen."},{t:2,s:"Das Erdbeben war sehr stark."},{t:3,s:"Wir haben das Erdbeben unbeschadet überstanden."},{t:4,s:"Das Erdbeben hat die Stadt erschüttert."},{t:5,s:"Nach dem Erdbeben gab es viele Nachbeben."}]},
  "earthquakes": {label:"Erdbeben",gender:"das",plural:"Erdbeben", ex5:[{t:1,s:"Japan erlebt jedes Jahr viele Erdbeben."},{t:2,s:"Wir haben heute in der Schule geübt, was man bei Erdbeben tun muss."},{t:3,s:"Moderne Gebäude sind so konstruiert, dass sie starken Erdbeben standhalten."},{t:4,s:"Erdbeben sind in dieser Region keine Seltenheit."},{t:5,s:"Die Wissenschaft erforscht die Ursachen von Erdbeben."}]},
