  "eclipse": {label:"Finsternis",gender:"die",plural:"Finsternisse", ex5:[{t:1,s:"Wir haben die Sonnenfinsternis beobachtet."},{t:2,s:"Der Mond verursachte eine kurze Finsternis."},{t:3,s:"Ihr Talent stellte alle anderen in den Schatten."},{t:4,s:"Die totale Finsternis war ein beeindruckendes Ereignis."},{t:5,s:"Er erlebte eine Mondfinsternis in den Bergen."}]},
  "eclipsed": {label:"verfinstert",gender:"",plural:"—", ex5:[{t:1,s:"Der Mond verfinstert die Sonne vollständig."},{t:2,s:"Ihr Talent verfinstert alle anderen Teilnehmer der Show."},{t:3,s:"Die Freude über den Sieg wurde durch die traurige Nachricht verfinstert."},{t:4,s:"Seine Erfolge wurden durch den Skandal verfinstert."},{t:5,s:"Das Licht wurde durch den Schatten verfinstert."}]},
  "eclipses": {label:"verfinstert",gender:"",plural:"—", ex5:[{t:1,s:"Eine Mondfinsternis tritt ein, wenn die Erde den Mond verfinstert."},{t:2,s:"Sein Talent verfinstert oft alle anderen im Raum."},{t:3,s:"Das neue Projekt verfinstert alle unsere bisherigen Bemühungen."},{t:4,s:"Der Mond verfinstert regelmäßig das Sonnenlicht."},{t:5,s:"Ihre Leistung verfinstert die der Konkurrenz."}]},
  "eclipsing": {label:"verfinsternd",gender:"",plural:"—", ex5:[{t:1,s:"Das neue Stadion wirkt verfinsternd auf alle anderen Gebäude der Stadt."},{t:2,s:"Der Mond ist dabei, die Sonne in diesem seltenen Ereignis zu verfinstern."},{t:3,s:"Ihr Talent ist dabei, das ihrer berühmten Schwester zu übertreffen."},{t:4,s:"Die dunkle Wolke zieht verfinsternd über das Land."},{t:5,s:"Er arbeitet hart, um die Konkurrenz zu verfinstern."}]},
  "eco": {label:"Öko-",gender:"",plural:"—", ex5:[{t:1,s:"Wir sollten beim Einkauf Öko-Taschen verwenden."},{t:2,s:"Das Unternehmen konzentriert sich auf eine ökologische Produktion."},{t:3,s:"Sie bauen ein Öko-Dorf in der Nähe des Waldes."},{t:4,s:"Öko-Produkte sind heute sehr gefragt."},{t:5,s:"Er lebt einen sehr bewussten Öko-Stil."}]},
