  "emcee": {label:"Moderator",gender:"der",plural:"Moderatoren", ex5:[{t:1,s:"Der berühmte Schauspieler wird heute Abend als Moderator durch die Preisverleihung führen."},{t:2,s:"Sie hat als Moderatorin für unsere Schulveranstaltung tolle Arbeit geleistet."},{t:3,s:"Der Moderator stellte den nächsten Redner mit einem breiten Lächeln vor."},{t:4,s:"Er ist ein sehr erfahrener Moderator."},{t:5,s:"Die Moderatorin begrüßte das Publikum herzlich."}]},
  "emendation": {label:"Verbesserung",gender:"die",plural:"Verbesserungen", ex5:[{t:1,s:"Der Autor nahm vor der Veröffentlichung mehrere Verbesserungen am Manuskript vor."},{t:2,s:"Diese Ausgabe bietet eine willkommene Verbesserung des Originaltextes."},{t:3,s:"Wir müssen mögliche Verbesserungen am geplanten Vorhaben diskutieren."},{t:4,s:"Diese Änderung ist eine echte Verbesserung."},{t:5,s:"Kleine Verbesserungen machen den Text klarer."}]},
  "emerald": {label:"Smaragd",gender:"der",plural:"Smaragde", ex5:[{t:1,s:"Die Krone trug einen makellosen Smaragd."},{t:2,s:"Ein Smaragd leuchtete tiefgrün im Licht."},{t:3,s:"Sie trug eine Kette mit einem Smaragd."},{t:4,s:"Dieser Smaragd ist von sehr hoher Qualität."},{t:5,s:"Ein Smaragd ist ein wertvoller Edelstein."}]},
