  "emojis": {label:"Emojis",gender:"",plural:"—", ex5:[{t:1,s:"Ich verwende viele Emojis, wenn ich meinen Freunden schreibe."},{t:2,s:"Glaubst du, dass diese Emojis meine Gefühle gut ausdrücken?"},{t:3,s:"Die App hat ihre Sammlung an Emojis aktualisiert."},{t:4,s:"Emojis machen Textnachrichten lebendiger."},{t:5,s:"Es gibt mittlerweile tausende verschiedene Emojis."}]},
  "emollient": {label:"Emolliens",gender:"das",plural:"Emollientien", ex5:[{t:1,s:"Die Creme ist ein beruhigendes Emolliens."},{t:2,s:"Eine Emolliens-Lotion linderte ihre trockene Haut."},{t:3,s:"Er wählte sanfte, Emolliens-artige Worte, um sie zu beruhigen."},{t:4,s:"Das Produkt dient als wirksames Emolliens."},{t:5,s:"Bei Hautproblemen hilft oft ein spezielles Emolliens."}]},
  "emolument": {label:"Emolument",gender:"das",plural:"Emolumente", ex5:[{t:1,s:"Die Stelle war mit einem großzügigen Emolument verbunden."},{t:2,s:"Er lehnte jedes Emolument für die Freiwilligenarbeit ab."},{t:3,s:"Das Gesetz begrenzt das Emolument, das ein Beamter erhalten darf."},{t:4,s:"Das Emolument für diese Position ist sehr hoch."},{t:5,s:"Ein angemessenes Emolument ist für die Arbeit wichtig."}]},
  "emoluments": {label:"Emolumente",gender:"",plural:"—", ex5:[{t:1,s:"Der Vertrag legt die Emolumente für die Position genau fest."},{t:2,s:"Seine gesamten Emolumente setzen sich aus Grundgehalt und Boni zusammen."},{t:3,s:"Der Vorstand diskutierte über die Emolumente für den neuen CEO."},{t:4,s:"Die Emolumente wurden bei der Verhandlung besprochen."},{t:5,s:"Zu den Emolumenten zählen auch verschiedene Nebenleistungen."}]},
  "emory": {label:"Emory",gender:"",plural:"—", ex5:[{t:1,s:"Sie studiert Jura an der Emory University."},{t:2,s:"Emory hat einen wunderschönen Campus in Atlanta."},{t:3,s:"Mein Bruder hat letztes Jahr sein Studium in Emory abgeschlossen."},{t:4,s:"Die Emory University ist für ihre Forschung bekannt."},{t:5,s:"Viele Studenten träumen von einem Platz in Emory."}]},
