  "emotional": {label:"emotional",gender:"",plural:"—", ex5:[{t:1,s:"Das war ein sehr emotionaler Moment."},{t:2,s:"Er reagierte ziemlich emotional."},{t:3,s:"Sie führten ein emotionales Gespräch."},{t:4,s:"Lass uns nicht emotional werden."},{t:5,s:"Das Thema ist sehr emotional."}]},
  "emotionally": {label:"emotional",gender:"",plural:"—", ex5:[{t:1,s:"Er ist emotional erschöpft."},{t:2,s:"Sie sind emotional sehr verbunden."},{t:3,s:"Es ist schwer, emotional stabil zu bleiben."},{t:4,s:"Sie reagierte emotional aufgelöst."},{t:5,s:"Er war emotional tief berührt."}]},
