  "emperor": {label:"Kaiser",gender:"der",plural:"Kaiser", ex5:[{t:1,s:"Der Kaiser regierte das große Reich."},{t:2,s:"Viele Menschen fürchteten den Kaiser."},{t:3,s:"Im Unterricht haben wir über den Kaiser gesprochen."},{t:4,s:"Der Kaiser wohnte in einem prächtigen Schloss."},{t:5,s:"Die Macht des Kaisers war unbegrenzt."}]},
  "emperors": {label:"Kaiser",gender:"die",plural:"—", ex5:[{t:1,s:"Das Buch erzählt die Geschichten alter Kaiser."},{t:2,s:"Viele Kaiser bauten prächtige Paläste."},{t:3,s:"Die Macht der Kaiser änderte sich im Laufe der Zeit."},{t:4,s:"Römische Kaiser hatten großen Einfluss."},{t:5,s:"Diese Kaiser regierten das Land mit eiserner Hand."}]},
  "emphasis": {label:"Betonung",gender:"die",plural:"Betonungen", ex5:[{t:1,s:"Die Betonung hat sich im Laufe des Gesprächs verschoben."},{t:2,s:"Die Betonung auf diesem Wort ist sehr wichtig."},{t:3,s:"Wir legen großen Wert auf die richtige Betonung."},{t:4,s:"Die Betonung liegt auf der ersten Silbe."},{t:5,s:"Seine Erklärung hatte eine klare Betonung."}]},
  "emphasise": {label:"betonen",gender:"",plural:"—", ex5:[{t:1,s:"Der Lehrer möchte die Bedeutung des Lesens betonen."},{t:2,s:"Sie müssen die Hauptpunkte in Ihrer Präsentation betonen."},{t:3,s:"Er versucht immer, seine Herkunft zu betonen."},{t:4,s:"Wir sollten diese wichtige Regel betonen."},{t:5,s:"Der Trainer möchte die Schnelligkeit im Training betonen."}]},
