  "emphasising": {label:"betonend",gender:"",plural:"—", ex5:[{t:1,s:"Er sprach laut, die Wichtigkeit des Lesens betonend."},{t:2,s:"Sie zeigte auf die Grafik, den Unterschied betonend."},{t:3,s:"Der Chef nickte freundlich, seine Zustimmung betonend."},{t:4,s:"Er machte eine Geste, seine Worte betonend."},{t:5,s:"Sie schrieb den Brief, ihre Entschuldigung betonend."}]},
  "emphasize": {label:"betonen",gender:"",plural:"—", ex5:[{t:1,s:"Die Trainer wollen die Bedeutung von Grundübungen betonen."},{t:2,s:"Der Chef möchte die Sicherheit am Arbeitsplatz betonen."},{t:3,s:"Wir müssen diese wichtige Regel betonen."},{t:4,s:"Meine Mutter möchte eine gesunde Ernährung betonen."},{t:5,s:"Lehrer wollen oft die Wichtigkeit von Hausaufgaben betonen."}]},
  "emphasized": {label:"betonte",gender:"",plural:"—", ex5:[{t:1,s:"Der Lehrer betonte die Wichtigkeit des Lesens."},{t:2,s:"Er betonte, dass Sicherheit an erster Stelle steht."},{t:3,s:"Der Bericht betonte die Notwendigkeit für neue Veränderungen."},{t:4,s:"Sie betonte die Rolle der Kommunikation im Team."},{t:5,s:"Der Trainer betonte die Ausdauer im letzten Spiel."}]},
  "emphasizes": {label:"betont",gender:"",plural:"—", ex5:[{t:1,s:"Der Bericht betont die Bedeutung von Teamarbeit."},{t:2,s:"Meine Mutter betont immer eine gesunde Ernährung."},{t:3,s:"Der Trainer betont die Schnelligkeit in jedem Training."},{t:4,s:"Dieses Buch betont die Wichtigkeit der Praxis."},{t:5,s:"Er betont oft seine jahrelange Erfahrung."}]},
  "emphasizing": {label:"betonend",gender:"",plural:"—", ex5:[{t:1,s:"Der Lehrer spricht, die Wichtigkeit des Lesens betonend."},{t:2,s:"Sie wiederholte den Satz, die richtige Aussprache betonend."},{t:3,s:"Er erklärte den Plan, jeden einzelnen Schritt betonend."},{t:4,s:"Der Künstler malte das Bild, die feinen Details betonend."},{t:5,s:"Sie stand vor uns, ihre Unabhängigkeit betonend."}]},
  "emphatic": {label:"nachdrücklich",gender:"",plural:"—", ex5:[{t:1,s:"Sie gab eine nachdrückliche Absage."},{t:2,s:"Sein nachdrücklicher Ton ließ keinen Zweifel offen."},{t:3,s:"Das Team errang einen nachdrücklichen Sieg."},{t:4,s:"Er betonte seine Meinung in nachdrücklicher Weise."},{t:5,s:"Es war eine nachdrückliche Bitte um Hilfe."}]},
