  "emphysema": {label:"Lungenemphysem",gender:"das",plural:"Lungenemphyseme", ex5:[{t:1,s:"Rauchen ist eine Hauptursache für ein Lungenemphysem."},{t:2,s:"Er hat wegen seines Lungenemphysems Atembeschwerden."},{t:3,s:"Das Lungenemphysem verursacht bleibende Schäden an der Lunge."},{t:4,s:"Ein Lungenemphysem wird oft erst spät erkannt."},{t:5,s:"Die Therapie bei einem Lungenemphysem ist langwierig."}]},
  "empire": {label:"Reich",gender:"das",plural:"Reiche", ex5:[{t:1,s:"Das Reich ist untergegangen."},{t:2,s:"Das Reich erstreckte sich über viele Länder."},{t:3,s:"Wir haben im Unterricht viel über das römische Reich gelernt."},{t:4,s:"Die Geschichte zeigt den Aufstieg und Fall jedes Reichs."},{t:5,s:"Das Reich war für seine Kultur bekannt."}]},
  "empires": {label:"Reiche",gender:"die (Pl.)",plural:"Reiche", ex5:[{t:1,s:"Wir haben den Aufstieg und Fall antiker Reiche studiert."},{t:2,s:"Die Geschichte ist voller Geschichten über mächtige Reiche."},{t:3,s:"Die Karte zeigt die Grenzen verschiedener Reiche."},{t:4,s:"Viele Reiche sind im Laufe der Zeit verschwunden."},{t:5,s:"Man kann viel aus dem Vergleich alter Reiche lernen."}]},
  "empirical": {label:"empirisch",gender:"",plural:"—", ex5:[{t:1,s:"Sie stützten sich auf empirische Belege."},{t:2,s:"Die Behauptung mangelt an empirischer Grundlage."},{t:3,s:"Empirische Tests haben die Theorie bestätigt."},{t:4,s:"Wir brauchen empirische Daten für diese Studie."},{t:5,s:"Das ist eine empirische Untersuchung."}]},
  "empirically": {label:"empirisch",gender:"",plural:"—", ex5:[{t:1,s:"Diese Theorie wurde von vielen Wissenschaftlern empirisch überprüft."},{t:2,s:"Wir müssen diese Ergebnisse empirisch verifizieren, bevor wir sie veröffentlichen."},{t:3,s:"Die Studie zeigt empirisch den Zusammenhang zwischen Ernährung und Gesundheit."},{t:4,s:"Der Effekt lässt sich empirisch nachweisen."},{t:5,s:"Die Daten wurden empirisch erhoben."}]},
  "empiricism": {label:"Empirismus",gender:"der",plural:"—", ex5:[{t:1,s:"Die Wissenschaft stützt sich stark auf die Prinzipien des Empirismus."},{t:2,s:"Er bevorzugt den Empirismus gegenüber abstrakten Theorien bei der Problemlösung."},{t:3,s:"Das Fundament seiner Forschung beruht auf strengem Empirismus."},{t:4,s:"Der Empirismus betont die Bedeutung der Erfahrung."},{t:5,s:"Viele Philosophen haben sich mit dem Empirismus befasst."}]},
  "employ": {label:"beschäftigen",gender:"",plural:"—", ex5:[{t:1,s:"Firmen beschäftigen viele Mitarbeiter."},{t:2,s:"Das Werk beschäftigt derzeit mehr Leute als früher."},{t:3,s:"Wir beschäftigen eine neue Methode, um das Problem zu lösen."},{t:4,s:"Das Unternehmen möchte neue Experten beschäftigen."},{t:5,s:"Wie viele Leute beschäftigt diese Firma?"}]},
  "employability": {label:"Beschäftigungsfähigkeit",gender:"die",plural:"—", ex5:[{t:1,s:"Das Erlernen neuer Software-Kenntnisse verbessert Ihre Beschäftigungsfähigkeit auf diesem Markt."},{t:2,s:"Das Universitätsprogramm konzentriert sich darauf, die Beschäftigungsfähigkeit der Absolventen zu erhöhen."},{t:3,s:"Sprachkenntnisse sind ein Schlüsselfaktor für Ihre gesamte Beschäftigungsfähigkeit."},{t:4,s:"Praktika fördern die Beschäftigungsfähigkeit der Studenten."},{t:5,s:"Die Weiterbildung dient der Steigerung der Beschäftigungsfähigkeit."}]},
  "empowered": {label:"befugt",gender:"",plural:"—", ex5:[{t:1,s:"Das neue Gesetz hat die Polizei dazu befugt, schnell zu handeln."},{t:2,s:"Nach der Schulung fühlte sie sich gestärkt und befugt."},{t:3,s:"Der Manager hat seinem Team die Befugnis erteilt, Entscheidungen zu treffen."},{t:4,s:"Sie ist befugt, in dieser Angelegenheit zu unterschreiben."},{t:5,s:"Er fühlte sich durch das Vertrauen seines Chefs sehr befugt."}]},
  "empowering": {label:"stärkend",gender:"",plural:"—", ex5:[{t:1,s:"Neue Fähigkeiten zu erlernen, wirkt sehr stärkend."},{t:2,s:"Sie hielt eine stärkende Rede vor den Studenten."},{t:3,s:"Dieses Programm ist sehr stärkend für junge Führungskräfte."},{t:4,s:"Es ist eine stärkende Erfahrung, Verantwortung zu übernehmen."},{t:5,s:"Das Gespräch mit ihr war sehr stärkend für mein Selbstbewusstsein."}]},
  "empowerment": {label:"Ermächtigung",gender:"die",plural:"Ermächtigungen", ex5:[{t:1,s:"Bildung ist der Schlüssel zur Ermächtigung von Frauen."},{t:2,s:"Das Programm konzentriert sich auf die Ermächtigung der Jugend."},{t:3,s:"Wir glauben an die Ermächtigung unserer Mitarbeiter."},{t:4,s:"Die Ermächtigung des Einzelnen führt zu einer stärkeren Gesellschaft."},{t:5,s:"Ohne die nötige Ermächtigung kann das Team nicht effizient arbeiten."}]},
  "empowers": {label:"ermächtigen",gender:"",plural:"—", ex5:[{t:1,s:"Bildung ermächtigt Kinder, ihre Träume zu verwirklichen."},{t:2,s:"Dieses neue Gesetz ermächtigt die Polizei zum Eingreifen."},{t:3,s:"Wissen ermächtigt dich, bessere Entscheidungen zu treffen."},{t:4,s:"Die Verfassung ermächtigt die Regierung zum Handeln."},{t:5,s:"Diese Vollmacht ermächtigt ihn, in meinem Namen zu sprechen."}]},
  "empress": {label:"Kaiserin",gender:"die",plural:"Kaiserinnen", ex5:[{t:1,s:"Die Kaiserin regierte das Land viele Jahre lang."},{t:2,s:"Die Kaiserin lebte in einem prächtigen Palast."},{t:3,s:"Geschichtsbücher erzählen Geschichten über die mächtige Kaiserin."},{t:4,s:"Das Volk verehrte die Kaiserin für ihre Weisheit."},{t:5,s:"Die Kaiserin besuchte die Stadt bei strahlendem Sonnenschein."}]},
  "emptied": {label:"entleeren",gender:"",plural:"—", ex5:[{t:1,s:"Sie entleerte den Mülleimer, bevor sie das Haus verließ."},{t:2,s:"Er entleerte seine Taschen, um zu zeigen, dass er nichts hatte."},{t:3,s:"Das Stadion entleerte sich schnell, nachdem das Spiel zu Ende war."},{t:4,s:"Sie hat den Schrank vollständig entleert."},{t:5,s:"Der Kellner entleerte die Gläser von unserem Tisch."}]},
  "empties": {label:"entleeren",gender:"",plural:"—", ex5:[{t:1,s:"Er entleert jeden Morgen den Mülleimer."},{t:2,s:"Der Fluss entleert sich in den großen, blauen Ozean."},{t:3,s:"Sie entleert ihre Taschen, bevor sie die Wäsche wäscht."},{t:4,s:"Er entleert den Briefkasten jeden Tag."},{t:5,s:"Die Maschine entleert den Wassertank nach jedem Gebrauch."}]},
  "emptiness": {label:"Leere",gender:"die",plural:"—", ex5:[{t:1,s:"Sie spürte eine gewisse Leere nach der Party."},{t:2,s:"Die Leere des Hauses machte mich traurig."},{t:3,s:"Er versuchte, die Leere in seinem Leben mit Arbeit zu füllen."},{t:4,s:"Die Leere in seinem Blick war deutlich zu erkennen."},{t:5,s:"Nach dem Abschied fühlte ich eine tiefe innere Leere."}]},
  "empty": {label:"leer",gender:"",plural:"—", ex5:[{t:1,s:"Die Kiste ist leer."},{t:2,s:"Das Zimmer ist leer."},{t:3,s:"Wir leeren den Mülleimer, wenn er voll ist."},{t:4,s:"Die Flasche ist völlig leer."},{t:5,s:"Er starrte auf das leere Blatt Papier."}]},
  "emptying": {label:"entleerend",gender:"",plural:"—", ex5:[{t:1,s:"Er ist gerade dabei, den Mülleimer vor dem Gehen zu entleeren."},{t:2,s:"Der Kellner ist damit beschäftigt, die Gläser von unserem Tisch zu entleeren."},{t:3,s:"Sie entleert gerade ihre Taschen, um ihre verlorenen Schlüssel zu finden."},{t:4,s:"Er ist dabei, das alte Lagerhaus zu entleeren."},{t:5,s:"Sie ist gerade dabei, den Wassertank zu entleeren."}]},
  "enabled": {label:"ermöglichen",gender:"",plural:"—", ex5:[{t:1,s:"Die neue Software hat uns ermöglicht, effizienter zu arbeiten."},{t:2,s:"Das Stipendium hat den Schülern ermöglicht, an der Konferenz teilzunehmen."},{t:3,s:"Die Technologie hat es ermöglicht, sich von überall zu verbinden."},{t:4,s:"Dieser Zugang hat mir die Arbeit sehr ermöglicht."},{t:5,s:"Das neue Gesetz hat den Bürgern ermöglicht, ihre Rechte wahrzunehmen."}]},
  "enabler": {label:"Ermöglicher",gender:"der",plural:"Ermöglicher", ex5:[{t:1,s:"Indem sie ihm immer Geld gibt, wurde sie zum Ermöglicher seiner Spielsucht."},{t:2,s:"Der Manager ist ein Ermöglicher, der seinem Team bei Problemen hilft."},{t:3,s:"Er ist nicht nur ein Freund, sondern ein Ermöglicher ihres schlechten Verhaltens."},{t:4,s:"Man sollte kein Ermöglicher für die Fehler anderer sein."},{t:5,s:"Er fungiert oft als Ermöglicher für neue Projekte im Büro."}]},
