  "enshrine": {label:"verankern",gender:"",plural:"—", ex5:[{t:1,s:"Die Rechte sind im Gesetz verankert."},{t:2,s:"Sie haben sein Andenken in Stein verankert."},{t:3,s:"Die Charta verankert die Redefreiheit."},{t:4,s:"Diese Werte sind fest in unserer Verfassung verankert."},{t:5,s:"Wir müssen diese Prinzipien für die Zukunft verankern."}]},
  "enshrined": {label:"verankert",gender:"",plural:"—", ex5:[{t:1,s:"Das Prinzip ist in der Verfassung verankert."},{t:2,s:"Diese Erinnerungen sind für immer in meinem Herzen verankert."},{t:3,s:"Die Tradition ist tief in unserer Kultur verankert."},{t:4,s:"Diese Regelung ist fest in den Statuten verankert."},{t:5,s:"Das Recht auf freie Meinungsäußerung ist gesetzlich verankert."}]},
