  "eruption": {label:"Eruption",gender:"die",plural:"Eruptionen", ex5:[{t:1,s:"Die vulkanische Eruption zwang viele zur Evakuierung."},{t:2,s:"Wissenschaftler überwachen den Vulkan auf Anzeichen einer Eruption."},{t:3,s:"Die plötzliche Eruption von Wut überraschte alle."},{t:4,s:"Die Eruption war weithin sichtbar."},{t:5,s:"Wir untersuchen die Folgen der Eruption."}]},
