  "expedition": {label:"Expedition",gender:"die",plural:"Expeditionen", ex5:[{t:1,s:"Die Expedition brach auf."},{t:2,s:"Die Expedition ist sehr riskant."},{t:3,s:"Wir haben an der Expedition teilgenommen."},{t:4,s:"Die Expedition wurde gut vorbereitet."},{t:5,s:"Er kehrte von der Expedition zurück."}]},
  "expeditionary": {label:"expeditionär",gender:"",plural:"—", ex5:[{t:1,s:"Die Armee sandte eine expeditionäre Einheit in das entlegene Gebiet."},{t:2,s:"Sie bereiteten ihre expeditionäre Ausrüstung für die lange Reise vor."},{t:3,s:"Die expeditionäre Mission war trotz des Wetters erfolgreich."},{t:4,s:"Das Team war für seine expeditionäre Arbeit bekannt."},{t:5,s:"Die expeditionäre Truppe kehrte sicher zurück."}]},
  "expeditions": {label:"Expeditionen",gender:"die",plural:"Expeditionen", ex5:[{t:1,s:"Sie unternahmen mehrere Expeditionen, um den tiefen Dschungel zu erforschen."},{t:2,s:"Wissenschaftliche Expeditionen helfen uns, seltene Tiere zu verstehen."},{t:3,s:"Das Museum finanzierte letztes Jahr viele historische Expeditionen."},{t:4,s:"Expeditionen in die Arktis sind sehr gefährlich."},{t:5,s:"Die Expeditionen dauerten mehrere Monate."}]},
