  "experience": {label:"Erfahrung",gender:"die",plural:"Erfahrungen", ex5:[{t:1,s:"Erfahrung macht klug."},{t:2,s:"Diese Erfahrung ist sehr wertvoll."},{t:3,s:"Wir haben viel Erfahrung gesammelt."},{t:4,s:"Das ist eine neue Erfahrung für mich."},{t:5,s:"Erfahrung ist der beste Lehrmeister."}]},
